// Verhalen (STORIES) en bereidingsstappen (STEPS) per recept. Staan los van
// recipes.js en laden pas na het opstarten (zie useRecipeTexts in
// ThuisbarApp.jsx), zodat de app sneller start.
import { RECIPE_ALIASES } from "./recipes.js";
import { EXTRA_STORIES, EXTRA_STEPS } from "./data/recipeTextsExtra.js";
import { STORIES_2, STEPS_2 } from "./data/recipeTextsExtra2.js";
import { STORIES_3, STEPS_3 } from "./data/recipeTextsExtra3.js";

// Korte, feitelijke oorsprongsverhalen per recept, geen letterlijke citaten uit één bron,
// samengevat uit algemeen bekende cocktailgeschiedenis. Bij twijfelachtige/betwiste oorsprong
// is dat expliciet benoemd i.p.v. één versie als absolute waarheid te presenteren.
export const STORIES = {
  whiskey_sour: "De formule sterk-zuur-zoet is ouder dan het woord 'cocktail': zeelieden mengden al in de achttiende eeuw sterke drank met citrus en suiker, onder meer tegen scheurbuik. De Whiskey Sour zelf staat in 1862 in Jerry Thomas' \"How to Mix Drinks\", het eerste Amerikaanse barboek. Vertel je gasten dat elke 'sour' die ze ooit gedronken hebben (Margarita, Daiquiri, Amaretto Sour) in de kern deze drie ingrediënten deelt, en dat zij nu de oervorm proeven.",
  daiquiri: "Genoemd naar een mijnstadje bij Santiago de Cuba, waar de Amerikaanse mijningenieur Jennings Cox rond 1898 rum, limoen en suiker gemengd zou hebben; zo luidt in elk geval de legende. Ernest Hemingway maakte de cocktail wereldberoemd in de jaren '30 in bar El Floridita in Havana, waar barman Constantino Ribalaigua een droge versie zonder suiker en met dubbele rum voor hem maakte. Die variant heet nu de Hemingway Special of Papa Doble. Een simpele drie-ingrediënten-cocktail die, mits goed gemaakt met vers limoensap, tot de beste dranken ter wereld wordt gerekend. Laat je gasten niet foppen door de zoete slush-machine-versie die de naam een slechte reputatie gaf.",
  margarita: "De herkomst is fel omstreden: minstens vier mensen claimen de uitvinding tussen de jaren '30 en '40, waaronder societydame Margarita Sames die in 1948 in Acapulco naar eigen zeggen tequila, triple sec en limoen mixte voor haar gasten aan het zwembad. Waarschijnlijker is dat de cocktail voortbouwt op de Daisy: 'margarita' is Spaans voor 'madeliefje', en 'daisy' betekent hetzelfde in het Engels. Het is een familie sours die al eerder met brandy of whisky werd gemaakt. Wat vaststaat: het is de populairste cocktail met tequila ter wereld en de reden dat de meeste mensen ooit voor het eerst tequila proefden zonder er meteen spijt van te krijgen. Vertel erbij dat een goede Margarita altijd vers limoensap heeft, nooit uit een flesje 'margarita-mix'.",
  pisco_sour: "Bedacht rond 1920 door de Amerikaanse barman Victor Vaughen Morris in zijn eigen bar in Lima, Peru. Een Peruaanse cocktail dus, maar wel van een Amerikaan, op basis van de Peruaanse druivenbrandewijn pisco. Chili en Peru strijden al bijna een eeuw over wie de cocktail (en de pisco zelf) mag claimen; Peru viert er elk jaar een nationale Pisco Sour-dag voor, op de eerste zaterdag van februari. Het eiwit maakt een weelderig schuimkraagje. Vertel je gasten dat dat schuim, met een paar druppels bitters erop, het visitekaartje van de cocktail is.",
  gimlet: "Ontstaan bij de Britse marine in de negentiende eeuw. Matrozen kregen limoensap tegen scheurbuik, en vanaf 1867 was er Rose's Lime Cordial, een gezoet limoensap dat lang houdbaar was. Officieren mengden dat met hun gin. De naam zou verwijzen naar marinearts Sir Thomas Gimlette, al kan hij ook komen van de gimlet, een klein boortje. Raymond Chandler liet zijn detective Philip Marlowe in \"The Long Goodbye\" zeggen dat 'a real gimlet is half gin and half Rose's lime juice and nothing else'. Vertel erbij dat puristen nog steeds ruziën over cordial of vers limoensap. Allebei is legitiem; het zijn simpelweg twee verschillende dranken met dezelfde naam.",
  bees_knees: "Bedacht tijdens de Amerikaanse drooglegging (1920-1933), toen illegale 'bathtub gin' er vaak vreselijk naar rook en smaakte. Honing en citroen waren niet zomaar een smaakkeuze maar noodzakelijke camouflage om de ruwe, soms giftige huisgestookte gin te verdoezelen. De uitdrukking 'the bee's knees' betekende in de jaren '20 slang voor 'het allerbeste', precies wat de bartender met deze naam wilde beweren over zijn eigen creatie. Een mooi voorbeeld van hoe drooglegging, tegen de bedoeling in, tot een golf van creatieve cocktails leidde in plaats van minder drinken.",
  clover_club: "Genoemd naar een invloedrijke herenclub van journalisten en advocaten die begin twintigste eeuw maandelijks dineerde in het Bellevue-Stratford Hotel in Philadelphia, waar de cocktail de huisdrank was. Frambozensiroop en eiwit geven de drank een weelderige, roze schuimkraag die decennialang als 'te vrouwelijk' werd afgeschreven door een macho cocktailcultuur, tot de craft-cocktailbeweging van de jaren 2000 hem herontdekte als technisch meesterwerkje. Vertel je gasten gerust dat de mannen van de Clover Club deze roze drank zelf dronken. Het vooroordeel kwam pas veel later.",
  amaretto_sour: "Een Amerikaanse jaren-'70-en-'80-klassieker gebouwd op amaretto, de Italiaanse amandellikeur die eigenlijk vaak van abrikozenpitten wordt gemaakt in plaats van amandelen. Die amandelsmaak komt van benzaldehyde, dezelfde stof die marsepein zijn geur geeft. De cocktail werd in de jaren 2010 herontdekt door de Amerikaanse craft-cocktailscene, die de zoete, kant-en-klare mix verving door vers citroensap, eiwit en soms een scheut bourbon voor extra ruggengraat: een 'volwassen versie' van dezelfde drank die iedereen zich herinnert uit de studentenkroeg. Een leuk weetje om te delen: de bittere amandelgeur in amaretto is chemisch identiek aan wat marsepein zijn smaak geeft.",
  cosmopolitan: "Kreeg wereldfaam dankzij de televisieserie \"Sex and the City\", al bestond de cocktail al in de jaren '80. Barman Toby Cecchini maakte in 1988 in The Odeon in New York de versie die we nu kennen, met cranberrysap, citroenwodka, Cointreau en limoen; anderen claimen eerdere varianten in Miami en Provincetown. De roze kleur en het martiniglas maakten hem in de jaren '90 tot symbool van een tijdgeest. Vertel je gasten dat de mooie kleur uit de balans tussen cranberry en limoen komt, niet uit kleurstof.",
  sidecar: "Ontstaan in Parijs of Londen rond het einde van de Eerste Wereldoorlog. Volgens het bekendste verhaal is hij genoemd naar een Amerikaanse legerofficier die zich in het zijspan van een motor naar zijn vaste bar liet rijden. Zowel Frank Meier van de Ritz Bar in Parijs als Harry MacElhone worden als bedenker genoemd, en het is nooit beslecht. De klassieke uitvoering heeft een suikerrand op het glas. Vertel erbij dat het in feite een cognacversie is van dezelfde sterk-zuur-zoet-formule waar later ook de Margarita uit voortkwam.",
  ward_8: "Genoemd naar het achtste stemdistrict van Boston, en gemaakt om de herverkiezing van een lokale politicus te vieren in een beroemd restaurant genaamd Locke-Ober, ergens rond 1898. Het achtste district was destijds cruciaal voor Boston's politieke machinespelletjes, dus deze cocktail is letterlijk gedistilleerde verkiezingspolitiek. Met zowel citroen- als sinaasappelsap is het een van de vroegste voorbeelden van een sour met dubbele citrus, een truc die je later in talloze moderne cocktails terugziet.",
  aviation: "Bedacht door Hugo Ensslin, hoofdbarman van het Hotel Wallick in New York, en gepubliceerd in zijn boek \"Recipes for Mixed Drinks\" uit 1916, met crème de violette erin, die de cocktail een subtiel lila tintje en bloemige geur geeft. De likeur verdween decennialang van de markt, waardoor bijna een eeuw lang de meeste barmensen de Aviation zonder violette maakten en dachten dat dat altijd zo was geweest. Pas na 2007, toen crème de violette weer te koop kwam, kon de cocktail in zijn oorspronkelijke, lucht-blauwig-lila glorie herrijzen. Vertel je gasten dat ze nu een historisch 'verloren' recept proeven dat pas recent is terugontdekt.",
  between_the_sheets: "Een cocktail uit de jaren '20 of '30, uit dezelfde familie als de Sidecar, maar met rum naast de cognac; de naam suggereert precies wat je denkt. Hij wordt vaak toegeschreven aan Harry MacElhone van Harry's New York Bar in Parijs. Drie soorten drank (cognac, rum en triple sec) in balans gebracht door citroen, waardoor je nauwelijks proeft hoeveel alcohol erin zit. Een goede waarschuwing om aan je gasten door te geven.",
  brandy_crusta: "Uitgevonden in de jaren 1850 door Joseph Santini in New Orleans, en beschouwd als de rechtstreekse voorouder van zowel de Sidecar als de hele sour-familie met suikerrand. De 'crusta' (Italiaans/Latijn voor korst) verwijst naar de suikerrand op het glas, en de lange sliert sinaasappelschil die als binnenvoering in het glas wordt gelegd was destijds revolutionair genoeg om de drank beroemd te maken. Het is een van de oudste cocktails die nog steeds vrijwel ongewijzigd wordt gemaakt. Vertel je gasten dat ze een stukje voor-de-Sidecar-geschiedenis drinken.",
  casino: "Een gin-sour uit het begin van de twintigste eeuw, opgenomen in Hugo Ensslins boek uit 1916. Hij is gebouwd op Old Tom gin, een iets zoetere ginstijl, met maraschino en sinaasappelbitters naast citroen, een opbouw die je later in veel gin-sours terugziet. De naam verwijst vermoedelijk naar de casino's waar zulke drankjes aan een chic publiek werden geschonken. Een 'vergeten klassieker' die de afgelopen jaren weer wordt opgediept.",
  mary_pickford: "Genoemd naar Mary Pickford, een van de grootste sterren van de vroege Hollywood-stomme film en medeoprichter van United Artists, en bedacht in de jaren '20 in een bar in Havana toen Amerikaanse filmsterren massaal naar Cuba reisden om aan de drooglegging in eigen land te ontsnappen. Ananassap en grenadine geven de cocktail een zonnig, tropisch karakter dat helemaal past bij het beeld van glamoureuze Hollywood-types die in Havana neerstreken voor zon en rum. Vertel je gasten dat 'Hollywood op vakantie in Cuba' zo ongeveer de hele geschiedenis van de klassieke rum-cocktail heeft gevormd.",
  monkey_gland: "Een van de vreemdste cocktailnamen ooit, genoemd naar een inmiddels volledig weerlegde medische rage uit de jaren '20: de Russisch-Franse chirurg Serge Voronoff beweerde dat het inplanten van weefsel uit apenteelballen mannen zou verjongen. Barman Harry MacElhone van Harry's New York Bar in Parijs vond het een perfecte naam voor een gin-cocktail met sinaasappelsap, absint en grenadine: precies zo schokkend als bedoeld. Een goed verhaal om te vertellen vlak voordat iemand voorzichtig een eerste slok neemt.",
  paradise: "Een elegante gin-cocktail met abrikozenbrandy en sinaasappelsap. Het oudst bekende recept staat in Harry MacElhone's \"ABC of Mixing Cocktails\" uit 1922; de bekendste versie staat in het Savoy Cocktail Book van 1930, samengesteld door barman Harry Craddock in Londen. Craddock werkte jarenlang in Amerikaanse bars en keerde tijdens de drooglegging terug naar Engeland, waar hij met de American Bar van het Savoy een van de beroemdste bars ter wereld maakte. Een rustige, fruitige drank die laat zien hoe verfijnd de gin-cocktail al was in het interbellum.",
  white_lady: "Toegeschreven aan Harry MacElhone, die in 1919 in Ciro's Club in Londen een eerste versie maakte met crème de menthe. Pas later, in Parijs, werd het de gin-triple sec-citroen-versie die we nu kennen: dezelfde opbouw als de Sidecar en de Margarita, maar dan met gin. Het eiwit dat je er vaak in ziet, geeft de zijdeachtige witte kleur waar de naam bij past. Vertel je gasten dat MacElhone in de jaren '20 opvallend veel klassiekers op zijn naam heeft staan.",
  caipirinha: "Brazilië's nationale cocktail, gemaakt met cachaça. Die wordt gestookt van vers suikerrietsap, terwijl de meeste rum van melasse komt. Op het platteland werd de drank al begin twintigste eeuw gedronken. Een populair maar onbewezen verhaal wil dat hij begon als volksmiddel tegen de Spaanse griep in 1918, met limoen, knoflook en honing, en dat de cachaça er later bij kwam. De naam is een verkleinwoord van 'caipira', een woord voor iemand van het platteland. Vertel je gasten dat de limoen inclusief schil wordt gemuddeld: daar komt de aromatische diepte vandaan.",
  hemingway_special: "Bedacht in de jaren '30 door Constantino Ribalaigua Vert, de beroemde barman van El Floridita in Havana, voor zijn bekendste klant: Ernest Hemingway. Hemingway wilde dubbel zoveel rum en geen suiker; vaak wordt gezegd uit angst voor diabetes, die in zijn familie voorkwam. Ribalaigua voegde grapefruitsap en een beetje maraschino toe, waardoor de cocktail droger en scherper werd dan een gewone Daiquiri. Hij heet ook wel Papa Doble. Een mooi verhaal om te vertellen: deze cocktail is ontstaan uit de wensen van één vaste gast.",
  lemon_drop: "Bedacht in de jaren '70 door Norman Jay Hobday, eigenaar van de bar Henry Africa's in San Francisco, een van de eerste 'fern bars' met planten en lampen van gekleurd glas. De naam verwijst naar het gelijknamige citroensnoepje, en de suikerrand op het glas moet dat snoepgevoel bij elke slok nabootsen. Later werd hij ook populair als shotje. Een leuk contrast om te delen tegenover de negentiende-eeuwse klassiekers op je kaart.",
  canchanchara: "Vaak de oudste cocktail van Cuba genoemd, ontstaan in de negentiende eeuw in het binnenland, lang voordat de Daiquiri of Mojito bestonden. Cubaanse vrijheidsstrijders in de onafhankelijkheidsoorlogen tegen Spanje (1868-1898) dronken volgens de overlevering suikerrietbrandewijn met honing en limoen, verkwikkend en makkelijk te maken in het veld. Hij wordt traditioneel geschonken in een aardewerken kommetje. Vertel je gasten dat dit de rebellendrank was die voorafging aan alle beroemde Cubaanse cocktails die ze wél kennen.",
  dons_special_daiquiri: "Bedacht door Donn Beach (geboren Ernest Raymond Beaumont-Gantt), de excentrieke Amerikaan die in de jaren '30 in Hollywood de allereerste tiki-bar opende, Don the Beachcomber, en daarmee het hele tiki-genre uitvond. Zijn 'Special' Daiquiri voegt grapefruitsap en falernum toe aan de klassieke basis, en illustreert Donn's stijl: complexe, gelaagde rumcocktails die de illusie van een exotisch eiland moesten oproepen voor Amerikanen die nooit verder dan Los Angeles waren geweest. Vertel je gasten dat de hele tiki-cultuur, van de Mai Tai tot de Zombie, bij deze man begint.",
  new_york_sour: "Een negentiende-eeuwse Amerikaanse whiskey sour met een verrassende laatste stap: een scheutje rode wijn die je voorzichtig boven op de cocktail laat 'drijven' in plaats van te mengen. Het effect is zowel visueel (een donkerrode wijnlaag boven een goudgele cocktail) als functioneel: elke slok proeft anders, van fruitig-wijnig aan de bovenkant tot puur whiskey-zuur onderin. Vertel je gasten dat ze de wijn expres níet moeten roeren, dat gelaagde effect is precies het punt van de drank.",
  south_side: "Een gin-sour met muntblaadjes, met een verhaal dat teruggaat naar de drooglegging in Chicago: de zuidkant van de stad zou destijds gecontroleerd zijn door gangster Al Capone, terwijl de noordkant een rivaliserende bende had, en de munt zou zijn toegevoegd om de smaak van de matige, snel-gestookte illegale gin te verdoezelen. Het verhaal is niet met zekerheid te bewijzen, maar het idee dat zelfs de meest verfijnde gin-cocktails soms zijn ontstaan als camouflage voor slechte drank is op zich al een goed gesprek waard aan de bar.",
  spicy_fifty: "Een moderne klassieker van Salvatore Calabrese, bedacht in 2005 voor de opening van de Londense club Fifty. Vanillewodka, vlierbloesemsiroop, limoen en honing worden geshaket met twee dunne plakjes verse rode peper: een vroeg en invloedrijk voorbeeld van de pittige-cocktailtrend. Sinds 2020 staat hij op de officiële lijst van de International Bartenders Association. Vertel je gasten dat de pit uit verse peper komt, niet uit tabasco, en dat je met het aantal plakjes zelf bepaalt hoe heet hij wordt.",
  tommys_margarita: "Gemaakt door Julio Bermejo in zijn familierestaurant Tommy's Mexican Restaurant in San Francisco in de jaren '90, als reactie op de standaard-Margarita die volgens hem de goede tequila overstemde met triple sec. Door de triple sec te vervangen door agavesiroop liet Bermejo de tequila zelf weer proeven, en zijn versie wordt inmiddels door veel bartenders wereldwijd gezien als de betere, 'volwassen' Margarita. Vertel je gasten dat dit dé versie is als ze een echt goede tequila in huis hebben en die niet willen laten verdrinken in likeur.",
  trinidad_sour: "Een verrassende moderne klassieker (rond 2010, bartender Giuseppe Gonzalez in New York) die de gebruikelijke verhouding compleet omdraait: hier is Angostura bitters de hoofdingrediënt in plaats van een paar druppeltjes, en whisky speelt slechts een bijrol. Het resultaat is een diep amberkleurige, kruidig-bittere cocktail die niemand verwacht als je vertelt hoeveel bitters er eigenlijk in gaat, vaak meer dan 40 ml. Een perfecte drank om gasten te verrassen die denken dat ze alles al kennen.",
  grand_margarita: "Een rijkere versie van de klassieke Margarita, met Grand Marnier in plaats van (of naast) gewone triple sec. Grand Marnier is een sinaasappellikeur op basis van cognac, en geeft de cocktail een dieper, warmer karakter dan de standaardversie. Vertel je gasten dat dit de 'grote broer' is voor wie de gewone Margarita te licht vindt.",
  gin_basil_smash: "Een van de invloedrijkste moderne cocktails van de afgelopen twintig jaar, bedacht in 2008 door de Duitse barman Jörg Meyer in zijn bar Le Lion in Hamburg. Hij muddelt een flinke bos verse basilicum in de shaker en schudt die daarna hard met gin, citroen en suikersiroop, waardoor de drank felgroen wordt. Het idee verspreidde zich razendsnel over de wereld en inspireerde veel 'smashes' met andere kruiden. Vertel je gasten dat deze drank het bewijs is dat er nog steeds echt nieuwe klassiekers worden uitgevonden, niet alleen oude die worden herontdekt.",
  whiskey_smash: "Een negentiende-eeuwse Amerikaanse 'smash': een kleine variant van de julep, met gemuddelde munt en sterke drank. Jerry Thomas beschreef hem in 1862 als 'een julep in het klein'. Barman Dale DeGroff bracht de Whiskey Smash rond 2000 terug in de mode door ook partjes citroen mee te muddelen, wat de cocktail een frisse, kruidige intensiteit geeft. Vertel je gasten dat dit een van de oudste muddelcocktails is die nog steeds gedronken worden.",
  jack_rose: "Een Amerikaanse klassieker uit het begin van de twintigste eeuw op basis van applejack (Amerikaanse appelbrandy), populair genoeg om op te duiken in Hemingways roman \"The Sun Also Rises\" (1926). De roze kleur komt van grenadine. Over de naam bestaan meerdere verhalen: de kleur van de Jacqueminot-roos, of een berucht figuur uit de New Yorkse onderwereld met de bijnaam Jack Rose. Niemand weet het zeker. New Jersey, waar Laird's een van de oudste distilleerderijen van Amerika heeft, claimt de cocktail als lokale trots.",
  blood_and_sand: "Genoemd naar de Rudolph Valentino-stomme film \"Blood and Sand\" uit 1922 over een Spaanse stierenvechter, en voor het eerst gepubliceerd in Harry Craddocks Savoy Cocktail Book van 1930. Het is een van de weinige klassiekers die scotch whisky combineert met zoete vermout, Cherry Heering én sinaasappelsap, een combinatie die op papier vreemd klinkt maar in de praktijk verrassend soepel samensmelt. Vertel je gasten dat dit een goed voorbeeld is van hoe cocktailnamen vroeger vaak rechtstreeks uit de bioscoop kwamen, als een soort vroege filmmerchandising.",
  apple_martini: "Een typisch jaren-'90-'00-creatie, ontstaan toen appellikeur (sour apple) en wodka in Amerikaanse bars enorm in de mode kwamen als toegankelijk alternatief voor de klassieke, drogere Martini. Ondanks de naam is het geen 'echte' Martini in klassieke zin (geen vermout, geen olijf), maar eerder een zoete, felgroene wodka-cocktail die zijn naam dankt aan het gebruikte glas. Een goed moment om aan je gasten uit te leggen dat 'Martini' inmiddels vooral 'geserveerd in een martiniglas' betekent, niet noodzakelijk de klassieke gin-vermout-verhouding.",
  lychee_martini: "Een moderne, Aziatisch geïnspireerde cocktail die lychee-likeur combineert met wodka, ontstaan in de golf van 'fruit-Martini's' die vanaf de jaren '90 westerse cocktailkaarten overspoelden. Lychee, een zoet-bloemige vrucht uit Zuidoost-Azië en Zuid-China, werd via deze cocktails voor het eerst voor veel westerse drinkers een herkenbare smaak buiten de fruitschaal. Een mooi bruggetje om te vertellen hoe de cocktailwereld continu nieuwe smaken uit de hele wereld absorbeert.",
  washington_apple: "Een Amerikaanse studentenbar-klassieker uit de jaren '90/'00 op basis van whiskey, appellikeur en cranberrysap, genoemd naar de staat Washington, historisch de grootste appelproducent van de Verenigde Staten. Minder verfijnd dan de negentiende-eeuwse klassiekers op deze lijst, maar een goed voorbeeld van hoe elke decennium zijn eigen, laagdrempelige feestcocktails toevoegt aan de canon naast de oude meesterwerken.",
  jasmine: "Een moderne klassieker uit 1993, bedacht door barman Paul Harrington in het restaurant Townhouse in Emeryville, Californië. Een vriend vroeg hem iets te maken wat hij nog nooit had gemaakt. Harrington nam de Pegu Club als basis, verving de bitters door Campari en de limoen door citroen, en noemde de drank naar die vriend, Matt Jasmin (met een spelfout, zo bleek later). Door zijn boek \"Cocktails\" uit 1998 werd de drank bekend. Vertel je gasten dat hij verrassend naar grapefruit smaakt, terwijl er geen grapefruit in zit.",
  algonquin: "Genoemd naar het beroemde Algonquin Hotel in New York, waar in de jaren '20 de zogeheten 'Round Table' samenkwam, een kring scherpzinnige schrijvers en critici (onder wie Dorothy Parker) die er geregeld lunchten. De cocktail is een rustige mix van rye, droge vermout en ananassap; wie hem precies bedacht, is niet bekend. Vertel je gasten dat het hotel er nog steeds staat, al is de beroemde ronde tafel allang verdwenen.",
  bacardi_cocktail: "Zo onlosmakelijk verbonden met het merk Bacardi dat een Amerikaanse rechter er in 1936 zelfs over moest oordelen: het Hooggerechtshof van New York bepaalde dat een 'Bacardi Cocktail' wettelijk alléén met Bacardi-rum gemaakt mag worden, anders mag de naam niet gebruikt worden. Een unieke juridische voetnoot in de cocktailgeschiedenis. De drank zelf is in de kern een Daiquiri met een scheutje grenadine, simpel maar met een verrassend stevige juridische reputatie.",
  kamikaze: "Een jaren-'70-cocktail waarvan de herkomst wordt toegeschreven aan Japanse zakenlui in New York, al is het bewijs daarvoor dun. De naam verwijst naar de Japanse zelfmoordpiloten uit de Tweede Wereldoorlog, een gedurfde, voor westerse oren exotische naam die in die tijd vooral bedoeld was om indruk te maken, niet als historisch eerbetoon. Vaak als shotje gedronken, maar oorspronkelijk een volwaardige, in een glas geshakete sour.",
  pink_lady: "Genoemd naar een gelijknamig Broadway-toneelstuk uit 1911 en al decennia later nog altijd te vinden in elk klassiek barboek, dankzij de opvallend felroze kleur die van de grenadine komt. Ooit gezien als een 'damesdrankje', een etiket dat destijds bedoeld was als compliment voor de zachte, toegankelijke smaak, maar dat de cocktail sindsdien nooit meer helemaal kwijt is geraakt. Het eiwit geeft 'm een zijdezachte textuur die verrassend goed samengaat met de stevige appelbrandy.",
  scofflaw: "Bedacht in 1924 in Harry's New York Bar in Parijs, en vernoemd naar het Engelse woord 'scofflaw', letterlijk 'wetsverachter'. Dat woord won begin 1924 een Amerikaanse prijsvraag naar een scheldwoord voor mensen die de drooglegging negeerden. Amerikanen die in Parijse bars zaten terwijl thuis alcohol verboden was, dronken hem met een grijns. Een cocktail die letterlijk is vernoemd naar het overtreden van de wet.",
  twentieth_century: "Genoemd naar de Twentieth Century Limited, de luxetrein die van 1902 tot 1967 tussen New York en Chicago reed en gold als hét symbool van elegant, modern reizen. De cocktail, met Lillet Blanc en cacaolikeur naast gin en citroen, is bedacht door de Britse barman C.A. Tuck en verscheen in 1937 in het Café Royal Cocktail Book in Londen. Hij straalt dezelfde art-deco-verfijning uit als de trein waarnaar hij is vernoemd.",
  diamondback: "Ontstaan in de Diamondback Lounge van het Lord Baltimore Hotel in Baltimore, ergens tussen het einde van de drooglegging (1933) en 1951. De lounge was vernoemd naar de diamondback-moerasschildpad, het symbool van Maryland. Wie de combinatie van rye whiskey, appelbrandy en gele Chartreuse bedacht, is onbekend; het recept staat in Ted Saucier's \"Bottoms Up\" uit 1951. Daarna raakte hij lang vergeten, tot de moderne cocktailrevival hem weer opgroef.",
  ranch_water: "Een simpel, drie-ingrediënten-drankje uit West-Texas, ontstaan onder ranchers en cowboys die tequila met limoen en het lokale, extra bruisende Topo Chico-mineraalwater mengden na een lange dag buiten. De cocktail bleef decennialang een regionaal, ongeschreven geheim tot hij rond 2018 via sociale media plotseling landelijk (en daarna wereldwijd) populair werd als het 'nieuwe, lichte' tequila-drankje. Vertel je gasten dat het succes ervan vooral zit in wat er níet in zit: geen suiker, geen siroop, alleen tequila, limoen en bubbels.",
  kentucky_buck: "Een moderne klassieker, bedacht in 2008 door barman Erick Castro voor de lentekaart van Bourbon & Branch in San Francisco. Hij bouwt voort op de 'Buck'-familie (sterke drank, citrus en gember) uit het begin van de twintigste eeuw, hier met bourbon en gemuddelde aardbei: een knipoog naar Kentucky, waar het overgrote deel van alle bourbon vandaan komt. Een fruitiger, toegankelijker neefje van de Kentucky Mule.",
  jamaican_mule: "Een variant op de Moscow Mule uit 1941, waarbij de wodka wordt vervangen door pittige, funky Jamaicaanse donkere rum, een combinatie die de gemberbier nog nadrukkelijker naar voren laat komen dan het origineel. Net als zijn wodka-voorouder wordt hij traditioneel in een koperen beker geserveerd, al is dat inmiddels puur decoratief en niet langer marketing voor één specifiek merk zoals bij het origineel in de jaren '40.",
  shandy: "Een oude Britse traditie: bier gemengd met limonade of gemberbier. De naam is een verkorting van 'shandygaff', een negentiende-eeuwse Engelse term voor bier met gemberbier. In Duitsland heet vrijwel hetzelfde drankje 'Radler' ('fietser'): volgens de bekendste overlevering mengde de Beierse herbergier Franz Kugler in 1922 bier met citroenlimonade omdat er ineens duizenden dorstige fietsers langskwamen en zijn bier dreigde op te raken.",
  presbyterian: "Een Amerikaanse klassieker uit de negentiende eeuw waarvan de naam vermoedelijk verwijst naar de sobere, ingetogen Presbyteriaanse kerkgemeenschap, een ietwat ironische knipoog, aangezien de drank zelf gewoon whiskey met een lichte, verfrissende twist is. In de kern niets meer dan een Whiskey Highball met twee soorten bubbels (ginger ale én soda) in plaats van één, wat 'm net iets lichter en droger maakt dan de meeste andere whiskey-longdrinks.",
  gin_buck: "Onderdeel van de 'Buck'-familie (sterke drank, citroen en gemberdrank) die vanaf het begin van de twintigste eeuw in Amerikaanse barboeken opduikt als simpele, verfrissende longdrink. De Gin Buck is daarvan een van de meest klassieke uitvoeringen: gin, citroen en ginger ale over ijs. De later veel bekendere Moscow Mule is in feite een Buck met wodka.",
  toronto: "Een klassieker uit het begin van de twintigste eeuw. Het oudst bekende recept staat als 'Fernet Cocktail' in het boek van Robert Vermeire uit 1922, met de opmerking dat hij in Canada veel gedronken werd; de naam Toronto kreeg hij later. In de kern een whiskycocktail in Old Fashioned-stijl met een scheutje Fernet-Branca, wat een kruidig-bittere ondertoon geeft die je pas na een paar slokken echt gaat proeven.",
  black_manhattan: "Bedacht in 2005 door barman Todd Smith in San Francisco, als een donkerdere, kruidigere twist op de klassieke Manhattan: de zoete vermout wordt volledig vervangen door amaro, de bittere Italiaanse kruidenlikeur die van oorsprong als spijsverteringsdrank werd gedronken. Een goed voorbeeld van hoe de moderne cocktailscene klassiekers niet zomaar kopieert maar er weloverwogen op doorbouwt.",
  red_hook: "Genoemd naar een havenwijk in Brooklyn, New York, en bedacht in 2003 door barman Vincenzo Errico in de bar Milk & Honey. Hij is de eerste van een hele reeks cocktails die naar Brooklynse wijken zijn vernoemd en voortbouwen op de klassieke Brooklyn- en Manhattan-structuur. De Red Hook gebruikt rye, Punt e Mes en maraschino-likeur, voor een bitterzoete diepte met een vleugje kers.",
  greenpoint: "Genoemd naar een andere Brooklynse wijk en bedacht in 2006 door barman Michael McIlroy in de invloedrijke New Yorkse bar Milk & Honey, een van de bars die aan de basis stond van de wereldwijde 'craft cocktail'-revival. De Greenpoint voegt gele Chartreuse en twee soorten bitters toe aan een Manhattan-achtige basis, wat hem kruidiger en complexer maakt dan zijn buurman de Red Hook.",
  old_pal: "Het oudst bekende recept staat in Harry MacElhone's \"ABC of Mixing Cocktails\" uit 1922, waar hij de drank toeschrijft aan William 'Sparrow' Robertson, sportredacteur van de Parijse editie van de New York Herald. In de kern een Boulevardier met droge in plaats van zoete vermout (en rye in plaats van bourbon), wat de cocktail een stuk droger en scherper maakt. Een mooie illustratie van hoe één soort vermout een cocktail compleet kan laten kantelen.",
  oaxaca_old_fashioned: "Bedacht in 2007 door barman Phil Ward in de New Yorkse bar Death & Co, als een van de eerste cocktails die mezcal, destijds buiten Mexico een nichedrank, serieus op de kaart zette. Hij combineerde reposado-tequila met een kleiner deel rokerige mezcal in een gewone Old Fashioned-opbouw, en liet daarmee bartenders wereldwijd zien dat mezcal een volwaardige basis voor verfijnde cocktails kon zijn. Een cocktail die de mezcal-hausse van de jaren 2010 hielp inluiden.",
  improved_whiskey_cocktail: "Een negentiende-eeuwse 'verbetering' (improved) op de allereerste cocktail-definitie uit 1806 (sterkedrank, suiker, water, bitters): barman Jerry Thomas voegde in de jaren 1870 een likeurtje en een vleugje absint toe aan de simpele Old Fashioned-formule. De naam is dus letterlijk te lezen als een historisch statement: dit was, volgens de bartenders van toen, een verbeterde versie van wat later juist weer de 'ouderwetse' (old-fashioned) standaard zou worden.",
  perfect_martini: "De term 'perfect' in cocktailtaal betekent specifiek: gelijke delen droge én zoete vermout in plaats van slechts één soort, een negentiende-eeuwse conventie die je ook tegenkomt bij de Perfect Manhattan en Perfect Rob Roy. Bij de Martini levert dat een tussenvorm op die zoeter is dan de bekende droge versie, maar droger dan de originele, zoetere Martinez waar de Martini ooit uit voortkwam.",
  metropolitan: "Een negentiende-eeuwse Amerikaanse cocktail op basis van cognac en zoete vermout, in essentie een vroege bloedverwant van de Manhattan maar dan met brandy in plaats van whiskey. In die tijd waren cognac-cocktails minstens zo gangbaar als whiskey-cocktails, tot phylloxera de Europese wijngaarden decimeerde en whiskey het overnam als Amerika's favoriete basis.",
  journalist: "Een gin-cocktail uit het interbellum die onder meer in het Savoy Cocktail Book van 1930 staat, met een opbouw die doet denken aan de Martini en de Manhattan tegelijk: droge én zoete vermout, plus een vleugje triple sec, citroen en bitters. Waar de naam vandaan komt, is niet bekend; hij past in elk geval bij het beeld van journalisten die na de deadline aan de bar belandden.",
  satans_whiskers: "Een Prohibition-tijdperk-cocktail uit Harry Craddocks Savoy Cocktail Book van 1930, met een naam die exact het soort speelse, licht schandalige branding had die bartenders in die tijd gebruikten om saaie ingrediënten (gin, vermout, sinaasappelsap) spannend te laten klinken. Craddock nam 'm zelfs in twee varianten op, 'straight' en 'curled', al naar gelang welke oranje likeur je gebruikte.",
  income_tax_cocktail: "Uit het Savoy Cocktail Book van 1930, met een naam die ironisch verwijst naar de Amerikaanse federale inkomstenbelasting, die pas in 1913 was ingevoerd en dus nog stof tot klagen gaf. In de kern is het een Bronx-cocktail (gin, zoete en droge vermout, sinaasappelsap) met een scheutje bitters erbij.",
  adonis: "Vaak genoemd als de eerste cocktail die naar een Broadway-productie is vernoemd: de musical \"Adonis\" uit 1884 was de eerste Broadway-voorstelling die meer dan 500 keer werd gespeeld, en een New Yorkse bar eerde dat met deze sherry-cocktail. Met alleen sherry, vermout en bitters is het een van de lichtste 'stirred-down'-klassiekers op deze lijst, en een goed startpunt voor wie wil wennen aan cocktails zonder sterke drank als basis.",
  brooklyn: "Genoemd naar de stadswijk Brooklyn en voor het eerst opgetekend in 1908, als een soort 'tegenhanger' van de Manhattan-cocktail die naar het buureiland is vernoemd. Het oorspronkelijke recept vroeg om Amer Picon, een Franse bittere likeur die in de Verenigde Staten decennialang niet meer verkrijgbaar was, waardoor de meeste moderne versies, ook deze, een vergelijkbare Italiaanse amaro als vervanger gebruiken.",
  death_in_the_afternoon: "Bedacht door Ernest Hemingway zelf voor een cocktailboek uit 1935 waarin beroemdheden hun favoriete drankje deelden, en genoemd naar zijn eigen boek over Spaanse stierengevechten uit 1932. Zijn instructie was kort en berucht: 'Giet één ons absint in een champagneglas. Voeg ijskoude champagne toe tot het de juiste melkachtige ondoorzichtigheid heeft. Drink 3 tot 5 van deze langzaam op.' Vertel je gasten dat vijf glazen van dit spul precies is waarom de cocktail zijn reputatie heeft.",
  air_mail: "Een Cubaanse cocktail uit de jaren '30, gebouwd op dezelfde rum-honing-limoen-basis als de Bee's Knees maar dan met champagne getopt in plaats van gewoon geserveerd. De bubbels zouden de link met luchtpost (air mail) verklaren, destijds nog een snelle, glamoureuze nieuwigheid. Een minder bekende, maar even elegante tegenhanger van de beroemdere French 75.",
  french_76: "Een simpele twist op de klassieke French 75 uit de jaren '20, waarbij de gin wordt vervangen door wodka, vandaar het net iets hogere nummer '76'. Populair geworden in Amerikaanse cocktailbars als toegankelijker alternatief voor wie de kruidige gin-smaak van het origineel liever mist, zonder in te leveren op de feestelijke combinatie van citrus en champagne.",
  poinsettia: "Genoemd naar de gelijknamige felrode kerstbloem, en bedacht als een kerstversie van de Mimosa: cranberrysap in plaats van sinaasappelsap geeft de cocktail zijn karakteristieke diepe, feestelijke rode kleur. Een relatief jonge Amerikaanse traditie, populair geworden via kerstbrunches in de jaren '80-'90, maar inmiddels net zo vaste prik tijdens de decembermaand als de kerstboom zelf.",
  seelbach: "Lange tijd werd verteld dat deze cocktail in 1917 per ongeluk ontstond in het Seelbach Hotel in Louisville, Kentucky, toen een barman champagne in een Manhattan morste. In 2016 gaf barman Adam Seger toe dat hij de cocktail in 1995 zelf had bedacht, en het verhaal er ook bij had verzonnen om het hotel een eigen klassieker te geven. Het recept met bourbon, triple sec, flink wat bitters en bubbels is er niet minder lekker door. Vertel je gasten dat dit een mooi voorbeeld is van hoe een goed verhaal een cocktail beroemd kan maken, ook als het niet waar is.",
  cable_car: "Bedacht in 1996 door barman Tony Abou-Ganim in de Starlight Room van het Sir Francis Drake Hotel in San Francisco, en genoemd naar de beroemde kabeltrams die langs het hotel rijden. Hij combineert spiced rum met sinaasappellikeur en citroen, en de rand van kaneelsuiker geeft bij elke slok een warme, kruidige noot.",
  kingston_negroni: "Bedacht eind 2009 door barman Joaquín Simó in de New Yorkse bar Death & Co. Toen een importeur langskwam met de nieuwe Smith & Cross, een stevige Jamaicaanse rum, bouwde Simó er ter plekke een Negroni mee. Vandaar 'Kingston', de hoofdstad van Jamaica. Een goed voorbeeld van hoe de formule van de Negroni (bitter, zoet, sterk in gelijke delen) werkt met heel andere sterke dranken, zolang de balans maar klopt.",
  fog_cutter: "Een van de krachtigste creaties van Victor 'Trader Vic' Bergeron, de tiki-pionier achter de Mai Tai, met drie verschillende sterke dranken (rum, cognac én gin) in één glas. Trader Vic schreef er zelf over: 'Fog Cutter, hell. After two of these, you won't even see the stuff.' Na twee van deze zie je de mist niet eens meer. Vaak geserveerd met een drijflaag sherry, al is die in deze versie weggelaten voor de eenvoud.",
  rum_runner: "Bedacht in 1972 in de Tiki Bar van het Holiday Isle Resort in Islamorada, op de Florida Keys. Volgens het verhaal moest de bar van een voorraad bramenlikeur en bananenlikeur af, en zo ontstond deze zoete, fruitige rumcocktail. De naam verwijst naar de 'rum runners': smokkelaars die tijdens de Amerikaanse drooglegging rum vanuit het Caribisch gebied naar Florida brachten.",
  corn_n_oil: "Een van de oudste cocktails uit Barbados, met een naam die weinig te maken heeft met de ingrediënten. Vermoedelijk een knipoog naar de donkere kleur van de rum en falernum, die aan motorolie zou doen denken. Ondanks (of dankzij) de weinig aanlokkelijke naam is het een gewaardeerde klassieker in de Caribische cocktailtraditie, met wortels die mogelijk teruggaan tot de negentiende eeuw.",
  planters_punch: "Een van de oudste rumpunches uit het Caribisch gebied, met een bekend rijmpje als vuistregel voor de verhoudingen: 'one of sour, two of sweet, three of strong, four of weak' (zuur, zoet, sterk, slap). Dat rijmpje stond al in 1908 in de New York Times. De precieze oorsprong wordt door Jamaica en andere eilanden geclaimd, en talloze plantage-eigenaren beweerden het 'originele' recept te bezitten: een rijke geschiedenis voor zo'n eenvoudige punch.",
  dr_funk: "Genoemd naar Dr. Bernard Funk, een Duitse arts die eind negentiende eeuw op Samoa werkte en daar de schrijver Robert Louis Stevenson behandelde, die er in 1894 overleed. Funk zou een drankje van absint en limoen hebben aangeraden. In de jaren '30 maakte tiki-pionier Donn Beach er een rumcocktail van met deze naam. Absint en grenadine geven hem een ongewone, kruidige twist binnen de rumpunch-familie.",
  nuclear_daiquiri: "Een loeisterke Daiquiri-variant, bedacht in 2005 door de Londense barman Gregor de Gruyther in LAB Bar. Het origineel gebruikt overproof rum van 63% en groene Chartreuse van 55%, met limoen en falernum. De naam is precies zo bedoeld als hij klinkt: een waarschuwing. De Gruyther zei er zelf over dat geen garnering de kracht van deze cocktail kan weerstaan, en serveerde hem daarom zonder.",
  gold_rush: "Bedacht rond 2000 door barman T.J. Siegal in de invloedrijke New Yorkse bar Milk & Honey: in feite een Whiskey Sour met honingsiroop in plaats van suiker, een bourbon-neefje van de Bee's Knees. De naam verwijst naar de goudkleur van bourbon en honing samen, en naar de Amerikaanse goudkoorts. Binnen een paar jaar werd hij wereldwijd als moderne klassieker gezien.",
  brown_derby: "Genoemd naar het Brown Derby-restaurant in Los Angeles, waarvan het eerste filiaal de vorm had van een bolhoed en in de jaren '20 en '30 een trefpunt was van filmsterren. De cocktail zelf ontstond in de jaren '30 in de Vendôme Club in Hollywood. Bourbon, grapefruit en honing: een frisse drank die verbonden bleef met de glamour van het gouden tijdperk van Hollywood.",
  eastside: "Een moderne klassieker uit de vroege jaren 2000, ontwikkeld in de New Yorkse cocktailscene als een frissere, kruidigere tegenhanger van de Southside, met komkommer toegevoegd aan de gin-munt-limoen-basis. De naam verwijst naar Manhattans Lower East Side, waar veel van de bars zaten die de moderne 'craft cocktail'-beweging vormgaven.",
  final_ward: "Bedacht in 2007 door barman Phil Ward in Death & Co in New York, dezelfde man achter de Oaxaca Old Fashioned, als variatie op de Last Word uit de jaren 1910. Ward verving de gin door rye whiskey en de limoen door citroen, maar hield de vier gelijke delen aan. Daarmee liet hij zien hoe flexibel de Last Word-formule is. De cocktail werd binnen een paar jaar zelf als moderne klassieker beschouwd.",
  pink_squirrel: "Een Amerikaanse dessertcocktail uit de jaren '50, genoemd naar zijn opvallende roze kleur, afkomstig van crème de noyaux, een amandelsmakende likeur die eigenlijk van perzik- of abrikozenpitten wordt gemaakt, net als amaretto. Ooit een gewaardeerd na-dinerdrankje in Amerikaanse steakhouses, tegenwoordig meer een curiositeit die af en toe door cocktailliefhebbers wordt herontdekt vanwege zijn ongewone kleur en smaak.",
  nutty_irishman: "Een romige jaren-'80-cocktail die Ierse room-likeur combineert met hazelnootlikeur, twee dranken die toevallig allebei in dezelfde periode wereldwijd furore maakten in de nasleep van het enorme succes van Baileys, dat in 1974 als allereerste room-likeur op de markt kwam. Een toegankelijke, zoete introductie tot de wereld van dessertcocktails.",
  separator: "Een romige na-dinercocktail uit dezelfde familie als de Brandy Alexander en de Mudslide: cognac, koffielikeur en room. Waar de naam vandaan komt en wie hem bedacht, is niet bekend. Een fijne, zachte afsluiter na het eten.",
  b52: "Een van de bekendste laagjesshooters ter wereld, uit de jaren '70. Een van de claims komt van barman Peter Fich in het Banff Springs Hotel in Canada, die drankjes naar zijn favoriete bands vernoemde; anderen zeggen dat de naam naar de Amerikaanse B-52-bommenwerper verwijst. Het geheim van de laagjes zit in de dichtheid van elke likeur: koffielikeur is het zwaarst en gaat onderin, dan roomlikeur, met de lichtere Grand Marnier bovenop.",
  melon_ball: "Een cocktail uit de jaren '80, uit dezelfde golf als de Sea Breeze en de Woo Woo, gebouwd op meloenlikeur. De bekendste daarvan is Midori, van het Japanse Suntory, dat in 1978 in de Verenigde Staten werd gelanceerd met een groot feest in de New Yorkse nachtclub Studio 54. De felgroene kleur maakte hem herkenbaar op elke bar uit die tijd, ook al is de drank inmiddels vooral een nostalgisch tijdsbeeld.",
  bushwacker: "Bedacht in 1975 in de Ship's Store op St. Thomas, op de Amerikaanse Maagdeneilanden: een bevroren, romige drank met koffielikeur, cacaolikeur en kokos. Barvrouw Linda Taylor proefde hem daar in 1977 en nam hem mee naar haar Sandshaker Bar in Pensacola Beach, Florida, waar ze hem met rum maakte. Daar werd hij zo populair dat de bar een machine voor bevroren drankjes moest kopen. Aan de Golfkust is hij nog altijd lokale trots, met jaarlijkse festivals.",
  hot_buttered_rum: "Een Amerikaanse koloniale traditie die teruggaat tot de achttiende eeuw, toen rum via de Caribische handelsroutes goedkoop en overvloedig beschikbaar was in de Amerikaanse koloniën, en boter en specerijen een simpele rum-borrel omtoverden tot een verwarmend winterdrankje. Decennialang vooral een landelijke, huiselijke traditie rond de kerstperiode, tegenwoordig weer terug op veel wintermenu's van cocktailbars.",
  tom_and_jerry: "Genoemd naar de gelijknamige personages uit een negentiende-eeuws Brits boek over het Londense nachtleven, lang vóór de latere, gelijknamige tekenfilmkat-en-muis bestond, en gepopulariseerd in Amerika door bartender Jerry Thomas, die het recept in zijn baanbrekende barboek uit 1862 opnam. De drank vereist een eigen, speciaal 'Tom and Jerry'-beslag van geklopt ei en suiker dat decennialang standaard in Amerikaanse huishoudens werd klaargemaakt rond de kerstdagen.",
  mulled_wine: "Een traditie die teruggaat tot het Romeinse Rijk, waar gekruide, verwarmde wijn al werd gedronken als middel om wijn van mindere kwaliteit smakelijker te maken en tegelijk het lichaam warm te houden in de winter. Vrijwel elk Europees land heeft zijn eigen versie en naam (Glühwein in Duitsland en Oostenrijk, vin chaud in Frankrijk), en de traditie is inmiddels onlosmakelijk verbonden met de Europese kerstmarkten.",
  virgin_pina_colada: "De alcoholvrije versie van Puerto Rico's nationale cocktail uit 1954, waarbij simpelweg de rum wordt weggelaten maar de weelderige ananas-kokos-combinatie die de Piña Colada wereldberoemd maakte volledig intact blijft. Populair bij kinderen op cruiseschepen en all-inclusive resorts, vaak zelfs geserveerd in hetzelfde uitbundige glas met parasolletje als het origineel.",
  roy_rogers: "Genoemd naar de gelijknamige Amerikaanse cowboyacteur en -zanger uit het midden van de twintigste eeuw, als alcoholvrij alternatief voor volwassenen die net als kinderen toch iets 'volwassens ogends' wilden drinken aan de bar. In de kern niet meer dan cola met grenadine, maar de naam en presentatie in een echt cocktailglas geven het net dat beetje meer status dan 'gewoon' een colaatje.",
  cinderella: "Een klassiek Europees mocktail-recept dat al decennia in barboeken verschijnt als het 'verplichte' alcoholvrije nummer naast de sterkere klassiekers. Vergelijkbaar met hoe elk sprookje zijn eigen vaste rol heeft, kreeg ook deze drie-sappen-mix een sprookjesnaam. Sinaasappel, citroen en ananas in balans gebracht met een vleugje grenadine bewijzen dat een mocktail net zo doordacht in elkaar kan zitten als elke andere cocktail op deze lijst.",
  gin_tonic: "Ontstaan bij Britten in India in de negentiende eeuw. Zij namen kinine tegen malaria, destijds het beste middel dat er was, maar dat smaakte extreem bitter. Opgelost in bruiswater met suiker werd het tonic, en met gin en limoen erbij werd de dagelijkse dosis een genoegen in plaats van een straf. Vertel je gasten dat moderne tonic nog altijd kinine bevat, alleen veel minder: genoeg voor de bittere smaak, maar lang niet genoeg om tegen malaria te beschermen.",
  cuba_libre: "Volgens de overlevering ontstaan rond 1900 in Havana, kort na de Spaans-Amerikaanse Oorlog, toen Amerikaanse soldaten de net geïmporteerde Coca-Cola mengden met Cubaanse rum en toostten op '¡Cuba libre!', 'een vrij Cuba', de strijdkreet uit de onafhankelijkheidsoorlog. Daarmee is het een van de weinige cocktails met een politieke naam. Vertel je gasten dat het verschil met een gewone rum-cola in het limoensap zit. Zonder dat is het geen Cuba Libre, gewoon rum met cola.",
  moscow_mule: "Ontstaan rond 1941 in Los Angeles. John Martin, die het wodkamerk Smirnoff had gekocht maar het in Amerika nauwelijks verkocht kreeg, sloeg de handen ineen met Jack Morgan, eigenaar van de bar Cock 'n' Bull, die met zijn eigen gemberbier bleef zitten. De koperen beker hoorde bij de verkooptruc: Martin ging met een polaroidcamera langs bars en fotografeerde barmannen met de drank. Zo hielp de Moscow Mule wodka in Amerika op de kaart te zetten. Vertel je gasten dat de koperen beker snel koud aanvoelt, waardoor de drank extra fris lijkt.",
  paloma: "Mexico's meest gedronken tequila-cocktail, populairder dan de Margarita in Mexico zelf, al is de exacte oorsprong onbekend. De naam betekent 'duif' in het Spaans, mogelijk verwijzend naar een oud Mexicaans volksliedje. Waar toeristen vaak een Margarita bestellen, grijpt de lokale bevolking naar een simpele Paloma: tequila met grapefruitfrisdrank en een schep zout. Vertel je gasten dat dit hét bewijs is dat de bekendste export-cocktail van een land niet altijd is wat de mensen zelf het liefst drinken.",
  dark_n_stormy: "Bermuda's nationale cocktail, gemaakt met Gosling's Black Seal Rum, en dat is geen vrijblijvende suggestie: Gosling's heeft de naam 'Dark 'n' Stormy' internationaal laten vastleggen als handelsmerk, dus een bar mag de naam officieel alleen gebruiken als hun eigen rum erin zit. De naam zou zijn bedacht door een marineofficier die de kleur van de drank vergeleek met een stormachtige lucht boven zee. Een van de weinige cocktails ter wereld waarbij het merk letterlijk in de receptuur is verankerd, een leuk juridisch weetje voor aan de bar.",
  mojito: "Cuba's beroemdste export, met wortels die mogelijk teruggaan tot de zestiende eeuw: volgens de overlevering dronken zeelieden toen al suikerrietbrandewijn ('aguardiente de caña') met munt en limoen, als middel tegen kwalen, lang voordat er gerijpte rum bestond. Ernest Hemingway zou in de bar La Bodeguita del Medio in Havana op de muur hebben geschreven: 'My mojito in La Bodeguita, my daiquiri in El Floridita'. Historici twijfelen sterk of hij dat ooit deed. Vertel je gasten dat je de munt zachtjes kneust, niet fijnstampt. Te hard muddelen maakt de drank bitter in plaats van fris.",
  long_island: "De bekendste claim komt van barman Robert 'Rosebud' Butt, die hem in 1972 in de Oak Beach Inn op Long Island bedacht voor een wedstrijd met triple sec. Met wodka, gin, rum, tequila en triple sec, aangevuld met citroen en een scheut cola, lijkt hij in het glas op ijsthee. Daardoor is hij berucht als een van de meest bedrieglijke cocktails ter wereld. Een goede waarschuwing om aan gasten mee te geven voordat ze een tweede bestellen.",
  americano: "Een van de oudste nog bestaande cocktails, ontstaan in de jaren 1860 in Milaan in de bar van Gaspare Campari, onder de naam 'Milano-Torino' (naar Campari uit Milaan en vermout uit Turijn). Volgens de overlevering kreeg hij de naam Americano omdat Amerikaanse toeristen hem zo graag dronken. James Bond bestelt hem in Ian Flemings eerste roman \"Casino Royale\" uit 1953. Vertel je gasten dat de Negroni hieruit is ontstaan, door de soda te vervangen door gin.",
  garibaldi: "Genoemd naar Giuseppe Garibaldi, de negentiende-eeuwse generaal die een centrale rol speelde in de eenwording van Italië, en oorspronkelijk simpelweg Campari met sinaasappelsap. De moderne, door bartenders herontdekte versie eist wel vers geperst sap in plaats van het pak uit de supermarkt. De cocktail werd de afgelopen tien jaar een van de populairste 'lage ABV'-drankjes wereldwijd, precies om zijn simpelheid en frisheid. Vertel je gasten dat het verschil tussen een matige en een geweldige Garibaldi voor 90% in de kwaliteit van het sinaasappelsap zit.",
  horses_neck: "Ontstaan in de jaren 1890 in Amerika als alcoholvrij drankje: ginger ale met een lange sliert citroenschil die over de rand van het glas hangt, als de nek van een paard. Al begin twintigste eeuw voegden mensen er bourbon of brandy aan toe, en die versie werd de bekendste. Vertel je gasten dat de lange citroenschil niet alleen versiering is: de olie uit de schil geeft de hele drank een citrusgeur.",
  sea_breeze: "Een versie met gin en grenadine bestond al in de jaren '20, maar de Sea Breeze die we nu kennen (wodka met cranberry- en grapefruitsap) werd in de jaren '80 populair, mede doordat cranberryproducent Ocean Spray recepten met cranberrysap promootte. Hij hoort bij dezelfde golf simpele, roze wodkacocktails waar later ook de Cosmopolitan uit voortkwam. Drie ingrediënten, geen shaker nodig.",
  sex_on_the_beach: "Bedacht in 1987 door barman Ted Pizio in Confetti's Bar in Fort Lauderdale, Florida, voor een wedstrijd van een drankdistributeur die perzikschnaps wilde verkopen tijdens de voorjaarsvakantie, als het strand vol Amerikaanse studenten lag. De provocerende naam deed de rest. Het werd een van de bekendste cocktails ter wereld, vooral bij mensen die niet vaak cocktails bestellen. Een goed voorbeeld van hoe een gedurfde naam soms meer voor de verkoop doet dan de drank zelf.",
  tequila_sunrise: "Wereldberoemd geworden dankzij The Rolling Stones, die de cocktail massaal dronken tijdens hun Amerikaanse tournee in 1972. Roadies en journalisten schreven erover, en de naam ging de wereld over. De gelaagde zonsopgang-look ontstaat doordat grenadine, dichter dan de rest van de drank, langzaam naar de bodem zakt in plaats van te mengen. Vertel je gasten dat ze de grenadine er ná de tequila en het sinaasappelsap voorzichtig doorheen moeten laten zakken met een lepel, nooit roeren, anders verdwijnt het hele zonsopgang-effect.",
  bloody_mary: "Barman Fernand Petiot claimde hem in de jaren '20 te hebben bedacht in Harry's New York Bar in Parijs, als combinatie van wodka en tomatensap; er zijn ook andere claims. Later, in New York, voegde hij zout, peper, cayennepeper, citroen en worcestersaus toe. De naam zou verwijzen naar de Engelse koningin Mary I, bijgenaamd 'Bloody Mary' om haar vervolging van protestanten, al is dat nooit bewezen. Tegenwoordig is de garnering soms een complete maaltijd op een prikker. Vertel je gasten dat de eerste versie volgens Petiot alleen wodka en tomatensap was.",
  fernandito: "Een Argentijnse klassieker: Fernet-Branca met cola, in Argentinië ook 'Fernet con Coca' genoemd. Argentinië drinkt meer Fernet-Branca dan welk land ook, vooral in de provincie Córdoba, ondanks (of dankzij) de intens bittere, medicinale smaak. Wat in Italië als digestief na het eten wordt gedronken, is in Argentinië hét drankje op elk feestje. Een mooi verhaal over hoe één drank in twee culturen een heel andere rol kan krijgen.",
  suffering_bastard: "Ontstaan tijdens de Tweede Wereldoorlog in Caïro, in de bar van het legendarische Shepheard's Hotel, bedacht door barman Joe Scialom voor Britse soldaten die kampten met kater én woestijnhitte tegelijk. De combinatie van gin, brandy, bitters en gemberbier zou volgens de overlevering zelfs de zwaarste 'suffering bastards' (lijdende klootzakken, in ruw Engels) weer op de been krijgen. Een cocktail met een letterlijk medicinale oorsprong middenin een wereldoorlog: een sterk verhaal voor bij een sterke drank.",
  kentucky_mule: "Een variant op de Moscow Mule waarbij de wodka wordt vervangen door bourbon. 'Kentucky' verwijst naar de staat waar ongeveer 95% van alle bourbon vandaan komt. Bourbon mag overal in de VS worden gestookt, maar sinds 1964 mag alleen whiskey uit de VS zo heten. Een mooi bruggetje om gasten te vertellen dat 'bourbon' een beschermde naam is, net als champagne.",
  el_diablo: "Een recept van Trader Vic (Victor Bergeron), een van de twee grondleggers van de tiki-cultuur naast Donn Beach; het staat in zijn boek uit 1946 als 'Mexican El Diablo'. De naam ('de duivel' in het Spaans) past bij de pittige combinatie van tequila, cassis, limoen en gemberbier. Tequila werd toen nog weinig in Amerikaanse bars gebruikt. Vertel je gasten dat dit een van de vroege tequilacocktails is, uit dezelfde tijd waarin de Margarita opkwam.",
  woo_woo: "Een typisch Amerikaanse jaren-'80-cocktail uit dezelfde familie als de Sea Breeze en Sex on the Beach (wodka, perzikschnaps en cranberrysap), bedacht in een tijd waarin Amerikaanse bars massaal zoete, felgekleurde, makkelijk te drinken cocktails introduceerden voor een nieuw, breder publiek dat niet was opgegroeid met klassiekers als de Martini of Manhattan. De onbeschaamd speelse naam past bij het hele decennium van cocktails die vooral leuk moesten zijn, niet per se verfijnd.",
  fuzzy_navel: "Simpelweg perzikschnaps met sinaasappelsap, ontstaan in de jaren '80 toen perzikschnaps-merken als DeKuyper actief campagne voerden om hun product in zoveel mogelijk simpele, herkenbare cocktails te krijgen. De naam is een woordspeling: 'fuzzy' (donzig) verwijst naar het perzikvel, 'navel' naar de navelsinaasappel, allebei letterlijk de ingrediënten in de naam verstopt. Een goed voorbeeld van hoe drankenmerken zelf soms de cocktailgeschiedenis hebben geschreven, puur voor de verkoop.",
  salty_dog: "Ontstaan in Amerika rond de jaren '50, oorspronkelijk met gin en later vooral met wodka. Het enige verschil met een Greyhound is de zoutrand op het glas. 'Salty dog' is Engelse spreektaal voor een doorgewinterde zeeman. Een mooi voorbeeld van hoe twee bijna identieke cocktails door één detail (het zout) een eigen naam kregen.",
  greyhound: "De ongezouten tweelingbroer van de Salty Dog: simpelweg wodka of gin met grapefruitsap, zonder zoutrand, genoemd naar de Amerikaanse Greyhound-bus-maatschappij, wiens logo een rennende hazewindhond is. De drank zelf dateert al van voor de Tweede Wereldoorlog en is een van de eenvoudigste twee-ingrediënten-cocktails die nog steeds op elke bar ter wereld te vinden is.",
  screwdriver: "Zou zijn ontstaan bij Amerikaanse oliearbeiders in het Midden-Oosten in de jaren '40-'50, die wodka met sinaasappelsap mengden in een glas en, bij gebrek aan een lepel, met een schroevendraaier roerden. Vandaar de naam. Wodka had toen nog nauwelijks voet aan de grond in de VS, en simpele mixers als deze waren cruciaal om het drankje daar salonfähig te maken. Een van de simpelste cocktails ter wereld met tegelijk een van de kleurrijkste ontstaansverhalen.",
  lynchburg_lemonade: "Bedacht rond 1980 door Tony Mason, eigenaar van een restaurant in Huntsville, Alabama, en genoemd naar Lynchburg, Tennessee, waar Jack Daniel's wordt gestookt. Jack Daniel's nam het recept over in zijn reclame, waarna Mason het merk aanklaagde; hij verloor. De county rond Lynchburg is nog altijd 'droog': drank verkopen is er sterk beperkt, al mag de distilleerderij inmiddels wel flessen verkopen en proeverijen houden. Whiskey, triple sec, citroen en frisdrank: een soort whiskeylimonade.",
  michelada: "Mexico's antwoord op de Bloody Mary, maar dan met bier in plaats van wodka: een negentiende- of vroeg-twintigste-eeuwse traditie van bier mengen met limoen, zout en hete saus, vaak gedronken als ontbijt-kater-remedie. De exacte oorsprong van de naam is onduidelijk; een populaire (twijfelachtige) theorie zegt dat het is samengesteld uit 'mi chela helada' ('mijn ijskoude biertje'). In Mexico is het net zo alledaags en gevarieerd als de Bloody Mary in de VS, met elke regio en zelfs elk gezin een eigen receptvariant.",
  snowball: "Een Britse kersttraditie die vooral in de jaren '70 een hoogtepunt beleefde: advocaat met limonade en een scheutje limoensap, decennialang hét symbool van ouderwetse Britse kerstborrels. In de jaren '90 raakte hij uit de mode, maar de laatste jaren beleeft hij een nostalgische comeback. Vertel je gasten dat dit een beetje de Britse kerstversie is van onze advocaat met slagroom.",
  pimms_cup: "Hét drankje van het Wimbledon-tennistoernooi, gemaakt met Pimm's No. 1, een likeur op basis van gin met kruiden en fruit. James Pimm, eigenaar van een Londense oesterbar, schonk zijn mengsel vanaf de jaren 1820 aan zijn gasten als hulpje voor de spijsvertering. Tijdens Wimbledon gaan er elk jaar honderdduizenden glazen doorheen, met komkommer, aardbei en munt. Vertel je gasten dat het precieze kruidenrecept van Pimm's volgens het merk maar bij een handjevol mensen bekend is.",
  blue_lagoon: "Toegeschreven aan Andy MacElhone, zoon van de beroemde Harry MacElhone, in het familiebedrijf Harry's New York Bar in Parijs, rond 1960. Blauwe curaçao bestond toen al decennia, maar deze cocktail maakte er een ster van: wodka, blauwe curaçao en citroenlimonade, met een kleur die meteen opvalt. Hij luidde een reeks kleurrijke cocktails in die later populair werden op tropische bars en in nachtclubs.",
  old_fashioned: "Een van de oudste cocktails ter wereld: de term 'cocktail' werd in 1806 in een Amerikaanse krant voor het eerst gedefinieerd als exact deze combinatie: sterkedrank, suiker, water en bitters. Toen bartenders later steeds fantasievoller mixdrankjes gingen maken, begonnen puristen weer te vragen om hun drankje 'op de ouderwetse manier' (the old-fashioned way). Vandaar de naam. Vertel je gasten dat zij, wanneer ze een Old Fashioned drinken, technisch gezien de oervorm proeven waar het woord 'cocktail' zelf ooit specifiek naar verwees, voordat het een verzamelnaam werd voor alles wat gemengd wordt.",
  negroni: "Volgens het bekendste verhaal ontstaan rond 1919 in Florence, toen graaf Camillo Negroni aan zijn barman vroeg om zijn Americano sterker te maken door de soda te vervangen door gin. De barman, Fosco Scarselli, deed dat en garneerde de drank met een schijfje sinaasappel in plaats van citroen, om de twee cocktails uit elkaar te houden. Simpel om te maken (gelijke delen gin, Campari en zoete vermout) maar lastig echt in balans te krijgen, wat hem tot een geliefde proefsteen voor bartenders maakt. Vertel je gasten dat wie de Negroni te bitter vindt, er vaak na een paar keer van gaat houden: het is een smaak die je leert waarderen.",
  sazerac: "Een van de oudste Amerikaanse cocktails, uit New Orleans. Apotheker Antoine Amédée Peychaud maakte er in de jaren 1830 zijn eigen kruidenbitters, die nog altijd te koop zijn als Peychaud's Bitters. In het Sazerac Coffee House werd in de jaren 1850 cognac van het merk Sazerac de Forge met die bitters geschonken, en zo kreeg de cocktail zijn naam. Toen de druifluis phylloxera later in de negentiende eeuw de Franse wijngaarden verwoestte, schakelden bartenders over op rye whiskey, de basis van de moderne Sazerac. Het glas wordt eerst met absint omgespoeld en leeggegoten, wat een subtiele anijsgeur achterlaat. Vertel je gasten dat die stap, hoe klein ook, nooit mag worden overgeslagen.",
  boulevardier: "Bedacht in de jaren '20 in Parijs door Erskine Gwynne, een rijke Amerikaan en uitgever van het tijdschrift The Boulevardier. Vandaar de naam, die zoiets betekent als 'man van de stad', een chique flaneur. Het recept staat in 1927 in Harry MacElhone's boek \"Barflies and Cocktails\". Het is in feite een Negroni met whiskey in plaats van gin. Vertel je gasten dat ze door alleen de gin te vervangen door bourbon kunnen schakelen tussen een Negroni en een Boulevardier: dezelfde formule met een andere basis.",
  vieux_carre: "Genoemd naar de Franse naam voor de French Quarter in New Orleans ('oude wijk'), en bedacht in 1938 door barman Walter Bergeron in het Hotel Monteleone. Dat hotel kreeg in 1949 zijn beroemde Carousel Bar, die langzaam ronddraait als een draaimolen en waar de cocktail nu nog wordt geschonken. De cocktail combineert cognac én rye whiskey met zoete vermout en Bénédictine: een dubbele basis die zeldzaam is en de drank een rijke, kruidige diepte geeft.",
  remember_the_maine: "Genoemd naar de strijdkreet 'Remember the Maine!' die de Amerikaans-Spaanse Oorlog in 1898 aanwakkerde na de mysterieuze ontploffing van het Amerikaanse slagschip USS Maine in de haven van Havana. De cocktail zelf, een Manhattan-variant met absint en kersenlikeur, dook pas decennia later op in Charles H. Bakers reisverslag-cocktailboek uit 1939 over Havana, met veel meer flair dan feitelijke oorlogsgeschiedenis. Een goed voorbeeld van hoe cocktailnamen soms grote historische gebeurtenissen aanhalen zonder er inhoudelijk echt iets mee te maken te hebben.",
  rusty_nail: "Een combinatie van scotch whisky en Drambuie, een likeur op basis van whisky, honing en kruiden. De combinatie bestaat al sinds de jaren '30, maar de naam Rusty Nail werd pas in de jaren '60 populair. Volgens de legende kreeg de familie MacKinnon het recept van Drambuie in 1746 van de Schotse troonpretendent Bonnie Prince Charlie, als dank voor hun hulp bij zijn vlucht. De naam 'roestige spijker' verwijst vermoedelijk naar de kleur. Vertel je gasten dat de likeur in hun glas volgens de overlevering een recept van bijna drie eeuwen oud heeft.",
  stinger: "Een negentiende-eeuwse Amerikaanse na-dinerdrank op basis van cognac en crème de menthe, ooit razend populair bij de Amerikaanse high society van de Gilded Age als digestief na een zwaar diner. De combinatie van sterke cognac met frisse munt zou de 'steek' (sting) in de naam verklaren: een korte, verfrissende klap na de maaltijd. Tegenwoordig een wat vergeten klassieker, maar ooit het equivalent van wat een espresso nu is: iets om het diner mee af te sluiten.",
  cardinale: "Een Negroni-variant waarbij de zoete vermout wordt vervangen door droge vermout, wat de cocktail een veel drogere, scherpere signatuur geeft dan zijn beroemdere neef. De naam ('kardinaal' in het Italiaans) past bij de familie van Italiaanse aperitief-cocktails rond Campari die allemaal in dezelfde Noord-Italiaanse bartraditie zijn geworteld. Een mooi voorbeeld om aan gasten te laten proeven hoe drastisch één woordje verschil, zoet versus droog, de hele smaak van een cocktail kan veranderen.",
  french_connection: "Genoemd naar de gelijknamige Oscar-winnende thriller uit 1971 over drugssmokkel tussen Frankrijk en New York, en simpelweg cognac gemengd met amaretto: een makkelijke, populaire after-dinner-drank uit de jaren '70. De cocktail heeft verder weinig met de film te maken behalve de Franse link via de cognac; het is vooral een voorbeeld van hoe populaire films in die tijd vaak als inspiratie dienden voor nieuwe drankjes op de kaart.",
  rabo_de_galo: "Brazilië's eigen klassieker in de Manhattan-familie, gemaakt met cachaça en zoete vermout. De naam betekent 'hanenstaart' in het Portugees: een letterlijke vertaling van het Engelse 'cocktail'. Hij werd in de jaren '50 populair, toen vermoutmerken Brazilianen vermout met cachaça leerden mengen. Minder bekend dan de Caipirinha, maar in Brazilië een serieuze cocktail voor wie verder kijkt dan limoen en suiker.",
  godfather: "Genoemd naar de maffiafilm uit 1972 van Francis Ford Coppola: scotch whisky met amaretto, een van de simpelste cocktails met twee ingrediënten die toch decennialang op Amerikaanse kaarten bleef staan. De combinatie van stevige whisky met zoete amandellikeur werd zo populair dat er al snel varianten kwamen, waaronder de wodkaversie: de Godmother.",
  godmother: "De wodka-variant van de Godfather: simpelweg wodka met amaretto in plaats van scotch whisky, bedacht als toegankelijker alternatief voor wie de rokerige whisky-smaak te uitgesproken vond. Een mooi, klein voorbeeld van hoe cocktailfamilies zich vaak vertakken: één simpele basisformule (sterkedrank plus amaretto) die met een andere spirit weer een compleet nieuwe naam en identiteit krijgt.",
  bb: "Bénédictine en cognac in gelijke delen, vandaar de naam B & B. Het werd in de jaren '30 populair in de New Yorkse '21' Club, en in 1937 bracht Bénédictine zelf een kant-en-klare B & B op de markt. Bénédictine werd in 1863 in Normandië bedacht door wijnhandelaar Alexandre Le Grand. Hij verkocht het met het verhaal dat het recept van benedictijner monniken uit de zestiende eeuw kwam. Volgens het merk kennen maar drie mensen tegelijk het geheime recept met 27 kruiden en specerijen.",
  whisky_mac: "Een Britse klassieker: scotch whisky met gemberwijn, een warmende drank voor koude dagen. Volgens de overlevering is hij genoemd naar kolonel Hector MacDonald, die hem in de negentiende eeuw in Brits-Indië bedacht. In Groot-Brittannië wordt hij nog altijd vooral in de herfst en winter gedronken.",
  mint_julep: "Hét drankje van de Kentucky Derby, de beroemde Amerikaanse paardenrace, waar het sinds 1938 de officiële drank is en waar in het raceweekend zo'n 120.000 Mint Juleps worden geschonken. De julep zelf is veel ouder: al rond 1800 dronken mensen in het zuiden van de VS sterke drank met munt en suiker over ijs, eerst vaak met cognac of rum en later met bourbon. Traditioneel gaat hij in een zilveren of tinnen beker. Vertel je gasten dat je die beker het best onderaan of aan de rand vasthoudt: dan blijft de mooie laag ijsaanslag aan de buitenkant zitten.",
  martini: "Misschien wel de beroemdste cocktail ter wereld, met een oorsprong die nog altijd wordt betwist. Wat vaststaat: de verhouding gin-vermout werd in de twintigste eeuw steeds droger. Rond 1900 was een Martini soms bijna half om half; decennia later wilden drinkers nog maar een vleugje vermout. James Bond bestelt de zijne in de boeken 'shaken, not stirred'. Vertel je gasten dat roeren eigenlijk de klassieke bereiding is: een geroerde Martini blijft helder en zijdezacht, een geshakete wordt troebel en iets waterachtiger.",
  manhattan: "Ontstaan in de jaren 1870 of 1880 in New York. De bekendste legende wil dat de cocktail werd bedacht voor een feest van Lady Randolph Churchill, de Amerikaanse moeder van Winston Churchill, in de Manhattan Club. Maar zij was op dat moment in Engeland, waar ze net haar zoon had gekregen. De combinatie van rye whiskey, zoete vermout en bitters werd hoe dan ook al snel dé drank van de stad die zijn naam draagt. Vertel je gasten dat de felrode cocktailkers pas rond de jaren '20 opkwam; daarvoor gebruikte men marasca-kersen uit maraschinolikeur.",
  vesper: "Bedacht door Ian Fleming, de schrijver van James Bond, en beschreven in de eerste Bond-roman \"Casino Royale\" uit 1953. Bond dicteert de barman precies het recept: drie delen gin, één deel wodka en een half deel Kina Lillet, goed shaken tot hij ijskoud is, met een dunne plak citroenschil. De cocktail is vernoemd naar Vesper Lynd, de vrouw op wie Bond in het boek verliefd wordt. Kina Lillet bestaat niet meer; Lillet Blanc is de gangbare vervanger. Vertel je gasten dat een romanpersonage hier een echte, nog altijd bestelde cocktail heeft voortgebracht.",
  martinez: "Door velen beschouwd als de directe voorloper van de Martini, ontstaan in de jaren 1860-1880 in Californië, mogelijk genoemd naar het stadje Martinez, hoewel San Francisco evenzeer aanspraak maakt op de eer. In tegenstelling tot de latere, drogere Martini gebruikt de Martinez zoete vermout, maraschino-likeur en Old Tom Gin (een zoetere gin-stijl die tegenwoordig weer terug is), wat 'm veel voller en zoeter maakt. Vertel je gasten dat als ze de Martinez proeven, ze eigenlijk de 'oervorm' van de Martini proeven, van vóórdat de cocktail decennialang steeds droger werd gemaakt.",
  hanky_panky: "Bedacht rond 1903 door Ada Coleman, een van de eerste vrouwelijke hoofdbartenders ter wereld, in de American Bar van het Savoy Hotel in Londen, voor de Britse acteur Charles Hawtrey, die na een zware werkdag om 'iets met een beetje pit' vroeg. Toen hij de eerste slok proefde, zou hij hebben uitgeroepen: 'By Jove! That is the real hanky-panky!', een Victoriaanse uitdrukking voor iets sluws of verrassends. Vertel je gasten dat Fernet-Branca, het kruidenbittertje dat de cocktail zijn pit geeft, dezelfde likeur is die in Argentinië met cola wordt gedronken als de Fernandito.",
  tuxedo: "Een negentiende-eeuwse Martini-variant, genoemd naar de exclusieve Tuxedo Park Club in de staat New York, een besloten, rijkeluisgemeenschap waar het kledingstuk 'tuxedo' (smoking) zijn Amerikaanse naam aan zou danken. De cocktail voegt maraschino-likeur en absint toe aan de klassieke gin-vermout-basis, wat 'm net iets zoeter en kruidiger maakt dan een gewone Martini. Een goed bruggetje om te vertellen dat zowel het kledingstuk als de cocktail hun naam aan dezelfde exclusieve club uit de negentiende eeuw danken.",
  rob_roy: "Ontstaan in 1894 in het Waldorf Hotel in New York, rond de première van de operette \"Rob Roy\" over de Schotse volksheld Robert Roy MacGregor, een soort Schotse Robin Hood. Als eerbetoon werd de whiskey in een Manhattan vervangen door scotch, en de naam bleef hangen. Vertel je gasten dat dit in feite een 'Schotse Manhattan' is: dezelfde formule, alleen de whisky komt uit een ander land.",
  bronx: "Bedacht rond 1900 door barman Johnny Solon in het Waldorf-Astoria in New York, en genoemd naar de Bronx Zoo, die net was geopend. In de jaren daarna was het een van de populairste cocktails van Amerika, naast de Martini en de Manhattan. De combinatie van gin met droge én zoete vermout en sinaasappelsap maakte hem fruitiger dan de meeste cocktails uit die tijd. Tegenwoordig grotendeels vergeten, maar een eeuw geleden bestelde heel New York hem.",
  gibson: "Een Martini met een zilveruitje in plaats van een olijf, met een ontstaansverhaal dat wisselt per verteller: de populairste versie wijst naar Charles Dana Gibson, de illustrator achter de beroemde 'Gibson Girl'-tekeningen, die zijn barman zou hebben gevraagd om 'm voor de grap iets anders te geven dan de gebruikelijke olijf. Een andere versie noemt zakenman Walter D.K. Gibson, die zilveruitjes gebruikte om zijn Martini's te onderscheiden van die van zijn collega's tijdens lange zakenlunches. Vertel je gasten dat het zilveruitje niet zomaar decoratie is: het geeft een subtiel zuur-zoute smaakaccent dat een olijf niet heeft.",
  dirty_martini: "Een Martini met een scheutje pekelvocht van olijven, wat de drank een zoute, hartige diepte geeft. 'Dirty' (vies) verwijst naar de troebele kleur. Al rond 1900 gebruikten barmannen olijven in een Martini, en president Franklin D. Roosevelt stond erom bekend dat hij graag Martini's met een scheut olijvenpekel mixte. Echt populair werd de Dirty Martini vanaf de jaren '90. Vertel je gasten dat hoe 'vuiler' (meer pekel) ze hem bestellen, hoe zouter en troebeler hij wordt.",
  corpse_reviver_1: "Onderdeel van een negentiende-eeuwse familie 'katerdrankjes'. De naam zegt het al: een 'lijk' (de zwaar aangeslagen drinker van de avond ervoor) weer tot leven wekken. Deze versie met cognac, calvados en zoete vermout staat in het Savoy Cocktail Book van 1930, met de tip hem vóór 11 uur 's ochtends te drinken. Vertel je gasten dat het idee van 'de hond die je gebeten heeft', de volgende ochtend een beetje van hetzelfde spul, al meer dan een eeuw oud is.",
  el_presidente: "Ontstaan in Havana tijdens de jaren '20, mogelijk vernoemd naar de toenmalige Cubaanse president Gerardo Machado, en razend populair bij Amerikanen die tijdens de drooglegging naar Cuba vluchtten om er legaal te kunnen drinken. De cocktail combineert witte rum met droge vermout, curaçao en grenadine tot een elegante, stirred-down-signatuurdrank van het rijke, kosmopolitische Havana van vóór de revolutie. Een mooi tegenwicht om te vertellen naast de bekendere, meer toeristische Cubaanse cocktails als de Mojito en Daiquiri.",
  bobby_burns: "Genoemd naar Robert Burns, Schotlands nationale dichter, en in essentie een Rob Roy met een scheutje Bénédictine toegevoegd voor extra kruidigheid en zoetheid. De cocktail wordt traditioneel geserveerd rond 25 januari, Burns Night, wanneer Schotten wereldwijd het leven en werk van de dichter vieren met haggis, whisky en toespraken. Een mooi weetje: dit is een van de weinige cocktails die specifiek gekoppeld is aan één jaarlijkse feestdag.",
  affinity: "Een cocktail uit het begin van de twintigste eeuw, rond 1907 opgetekend in New York, met scotch whisky, droge én zoete vermout en Angostura bitters. In feite een Manhattan-achtige opbouw, maar met Schotse whisky in plaats van Amerikaanse rye. De naam suggereert de 'affiniteit' tussen de ingrediënten, die ondanks hun verschillende karakter soepel samensmelten. Een relatief onbekende maar elegante klassieker voor wie verder wil kijken dan de Rob Roy.",
  bamboo: "Bedacht in de jaren 1890 door Louis Eppinger, een Duits-Amerikaanse barman die het Grand Hotel in Yokohama, Japan, leidde: een van de eerste beroemde westerse cocktails met een Aziatische geboorteplek. In plaats van sterke drank gebruikt de Bamboo droge sherry en droge vermout met een paar druppels bitters, wat hem ongewoon licht maakt. Vertel je gasten dat dit een van de weinige klassiekers is zonder sterke drank, en toch tot de grote cocktails wordt gerekend.",
  bijou: "Opgenomen door Harry Johnson, een van de invloedrijkste Amerikaanse barmannen van de negentiende eeuw, in zijn Bartender's Manual van 1900. De naam betekent 'juweel' in het Frans, en volgens de overlevering staat elk ingrediënt voor een edelsteen: gin voor de diamant, groene Chartreuse voor de smaragd, zoete vermout voor de robijn. Vertel je gasten dat ze drie 'edelstenen' in één glas drinken.",
  widows_kiss: "Bedacht door George Kappeler, barman van het Holland House Hotel in New York, en gepubliceerd in zijn boek \"Modern American Drinks\" uit 1895: appelbrandy met Bénédictine, gele Chartreuse en een paar druppels Angostura. Twee kruidenlikeuren die van oudsher met kloosters worden verbonden, samen met appel: een rijke, bijna dessertachtige cocktail. De naam suggereert een kus die zoet en troostrijk genoeg is om zelfs een weduwe op te vrolijken. Lang vergeten, en de laatste jaren weer opgepikt door bartenders.",
  tipperary: "Genoemd naar het Ierse graafschap Tipperary en het beroemde Eerste Wereldoorlog-soldatenlied \"It's a Long Way to Tipperary\", en gepubliceerd in Harry Craddocks Savoy Cocktail Book van 1930. De cocktail combineert Ierse whiskey met zowel groene Chartreuse als zoete vermout: een ongewone, kruidig-zoete driehoek die 'm onderscheidt van de meeste andere whiskey-cocktails uit die tijd.",
  angel_face: "Ook uit de Savoy Cocktail Book van 1930, en een van de zeldzame klassiekers die drie ingrediënten in exact gelijke delen combineert: gin, abrikozenbrandy en calvados (appelbrandy). De simpele, symmetrische opbouw maakt 'm favoriet bij bartenders die graag laten zien hoe drie sterke, uiteenlopende smaken toch in perfecte balans kunnen samenkomen zonder één druppel citrus of suiker.",
  tom_collins: "Genoemd naar een bizarre praktische grap die in 1874 door heel Amerika waaierde: mensen vertelden elkaar dat een zekere 'Tom Collins' in een café om de hoek kwaad over hen had lopen roddelen, waarna nieuwsgierige slachtoffers de stad introkken op zoek naar een man die niet bestond. De hoax werd zo beroemd dat een bartender besloot een cocktail naar de fictieve man te vernoemen. Het drankje zelf, gin, citroen, suiker en soda, bestond al eerder onder de naam John Collins, maar met Old Tom Gin (een zoetere gin-stijl) kreeg het zijn eigen naam. Vertel je gasten dit hele verhaal voordat je de vraag stelt: 'Heb jij Tom Collins al gezien?'",
  john_collins: "Volgens de overlevering genoemd naar John Collins, een negentiende-eeuwse ober in Limmer's Hotel in Londen, die beroemd was om zijn punch van jenever of gin met citroen, suiker en bruiswater. Toen bartenders er Old Tom gin voor gingen gebruiken, ontstond de Tom Collins, die veel bekender werd. In Amerika wordt een John Collins tegenwoordig meestal met bourbon gemaakt, zoals in deze versie.",
  french_75: "Genoemd naar het Franse 75mm-veldkanon uit de Eerste Wereldoorlog, bekend om zijn snelheid en kracht: precies wat deze cocktail van gin, citroen, suiker en champagne met de drinker doet. Een vroege versie verscheen rond 1915 in Parijs; de vorm die we nu kennen, staat in de jaren '20 in de boeken. Harry MacElhone van Harry's New York Bar wordt vaak als bedenker genoemd, maar dat is niet zeker. Vertel je gasten dat de bubbels de drank sneller laten werken dan je zou verwachten.",
  espresso_martini: "Bedacht in 1983 door de legendarische Londense barman Dick Bradsell, nadat een jong fotomodel aan de bar vroeg om 'iets dat me wakker maakt, en dan me dronken maakt' ('something to wake me up, and then f*** me up'). Bradsell improviseerde ter plekke met verse espresso, wodka en koffielikeur, en creëerde daarmee per ongeluk een van de meest gedronken moderne cocktails ter wereld. Vertel je gasten dat de dikke, bruine schuimlaag bovenop ontstaat door de cocktail hard te shaken. Zonder die schuimlaag mist de drank zijn handelsmerk.",
  kir_royale: "Genoemd naar Félix Kir, burgemeester van Dijon, Frankrijk, na de Tweede Wereldoorlog, die de lokale, minder aantrekkelijk geachte crème de cassis (zwartebessenlikeur) promootte door 'm te mengen met de plaatselijke witte wijn bij elk officieel bezoek aan de stad. De 'Royale'-versie met champagne in plaats van gewone witte wijn kwam pas later, als luxueuzere uitvoering voor feestelijke gelegenheden. Vertel je gasten dat deze cocktail dus letterlijk begon als een burgemeester die zijn eigen stad promootte via de borrel.",
  kir: "De originele, niet-mousserende versie van de Kir Royale: witte wijn (traditioneel bourgogne aligoté) met een scheutje crème de cassis, genoemd naar dezelfde burgemeester Félix Kir van Dijon. In Frankrijk nog altijd een alledaags aperitief, vaak als eerste drankje voor het diner geserveerd omdat het licht genoeg is om de eetlust niet te bederven.",
  bellini: "Uitgevonden in 1948 door Giuseppe Cipriani, oprichter van Harry's Bar in Venetië, en genoemd naar de Venetiaanse renaissanceschilder Giovanni Bellini vanwege de roze-oranje kleur die aan diens schilderijen zou doen denken. De cocktail vereist witte perziken, geen gewone gele perziken, voor de authentieke, zachte kleur en smaak, wat 'm oorspronkelijk een echt zomerdrankje maakte toen witte perziken in Italië rijp waren. Vertel je gasten dat Harry's Bar in Venetië nog steeds bestaat en nog altijd de Bellini serveert op de plek waar hij is uitgevonden.",
  mimosa: "Genoemd naar de gelijknamige gele mimosabloem vanwege de kleur, en bedacht in de jaren '20 in het Ritz Hotel in Parijs als elegante manier om champagne met sinaasappelsap te combineren voor het ontbijt. In de Verenigde Staten werd de cocktail vooral beroemd als hét symbool van de 'brunch'-cultuur die vanaf de jaren '30 in Amerikaanse hotels opkwam. Vertel je gasten dat de drank in Frankrijk soms ook wel 'Champagne-Orange' wordt genoemd, minder poëtisch dan de Amerikaanse naam.",
  gin_fizz: "Een negentiende-eeuwse Amerikaanse klassieker en directe voorouder van de beroemdere Ramos Fizz, waarbij gin, citroen en suiker met sodawater worden opgeschuimd tot een lichte, bruisende drank. De 'fizz'-familie ontstond als zomerse, verfrissende tegenhanger van de zwaardere, stirred-down-cocktails, en werd vooral 's ochtends of tijdens de lunch gedronken in de hitte van het zuiden van Amerika.",
  ramos_fizz: "Bedacht in 1888 door Henry C. Ramos in zijn bar in New Orleans, en berucht om het lange shaken dat nodig is om room, eiwit, oranjebloesemwater en citrus tot een dikke schuimlaag te kloppen. Ramos had op drukke momenten een hele rij 'shaker boys' die de shakers aan elkaar doorgaven. Het verhaal dat elke drank twaalf minuten werd geshaket, is overdreven; een paar minuten stevig shaken is genoeg. Vertel je gasten dat dit een van de meest arbeidsintensieve cocktails ter wereld is.",
  porto_flip: "Onderdeel van de 'flip'-familie. De eerste flips, in de zeventiende eeuw, waren warme dranken van bier, rum en suiker die met een gloeiend ijzer werden verhit, waardoor ze gingen schuimen. Later werd de flip een koude drank met ei. Deze versie met cognac, port en eigeel krijgt daardoor een romige, bijna dessertachtige textuur zonder melk of room. Vertel je gasten dat het ei de room vervangt: dat is het hele geheim van een flip.",
  champagne_cocktail: "Een van de oudste champagnecocktails die nog worden gedronken, al beschreven in Jerry Thomas' barboek uit 1862: een suikerklontje gedrenkt in Angostura bitters op de bodem van het glas, aangevuld met champagne en vaak een sinaasappelschil. Vertel je gasten dat het suikerklontje, terwijl het oplost, de belletjes extra laat opborrelen: een klein natuurkundig schouwspel in het glas.",
  french_martini: "Ontstaan in de jaren '80 in New York, gebouwd op wodka, framboos- of ananassap en Chambord, een Franse frambozenlikeur uit de Loire-vallei die naar verluidt teruggaat tot een recept van koning Lodewijk XIV. Ondanks de naam is de cocktail geen klassieke Martini in enige zin, maar hoort hij bij de golf 'fruit-Martini's' die eind twintigste eeuw de martiniglas-vorm losweekten van zijn strikte gin-vermout-oorsprong.",
  old_cuban: "Bedacht in 2001 door de Amerikaanse bartender Audrey Saunders, toen ze in het New Yorkse restaurant Beacon werkte; later schonk ze hem in haar beroemde bar Pegu Club, die in 2005 opende. Een Mojito met gerijpte rum in plaats van witte, getopt met champagne en een paar druppels Angostura. Het illustreert wat de moderne cocktailbeweging deed: oude ideeën herschikken tot iets nieuws. Vertel je gasten dat dit een van de jongste cocktails is die al 'klassiek' wordt genoemd.",
  porn_star_martini: "Bedacht in 2002 door de Britse bartender Douglas Ankrah in Londen, die de gedurfde naam bewust koos om op te vallen tussen de eindeloze rij Martini-varianten van die tijd. De cocktail combineert passievrucht met vanillewodka en wordt traditioneel geserveerd met een apart glaasje prosecco erbij om los op te drinken. Vertel je gasten dat die prosecco niet in de cocktail hoort, maar er als 'shot' naast wordt genuttigd, precies zoals Ankrah het bedoelde.",
  russian_spring_punch: "Bedacht door de Britse bartender Dick Bradsell, dezelfde man achter de Espresso Martini, als een fris, bessig punch-achtig drankje op basis van wodka, crème de cassis en champagne. Ondanks de naam heeft de cocktail geen historische Russische connectie; 'Russisch' verwijst simpelweg naar de wodka als basisingrediënt, een gewoonte die je bij veel Engelse cocktailnamen uit die tijd terugziet.",
  sherry_cobbler: "Een van de populairste Amerikaanse cocktails van de negentiende eeuw, zo geliefd dat buitenlandse bezoekers aan Amerika er in reisverslagen expliciet over schreven als typisch Amerikaans fenomeen. De cocktail introduceerde als een van de eersten het gebruik van fijngestampt ijs (crushed ice) in plaats van hele ijsblokken, wat destijds een technische noviteit was: ijs was voor de uitvinding van de koelkast een kostbaar goed dat 's winters uit meren werd gezaagd en in ijshuizen bewaard. Vertel je gasten dat fijngestampt ijs, dat nu overal vanzelfsprekend lijkt, ooit een radicale innovatie was die deze cocktail wereldberoemd maakte.",
  sloe_gin_fizz: "Een fizz met sloe gin: geen echte gin maar een Britse likeur, gemaakt door sleedoornbessen (wilde, wrange pruimpjes) in gin te laten trekken met suiker. Dat deden Engelse huishoudens al in de negentiende eeuw. De roze kleur en fruitig-kruidige smaak maken hem zoeter en toegankelijker dan een gewone Gin Fizz.",
  black_velvet: "Ontstaan in 1861 in Londen, in de Brooks's Club, als teken van nationale rouw na de dood van prins Albert, de echtgenoot van koningin Victoria. Zelfs de champagne moest 'rouw dragen', vandaar het mengen met donkere stout-bier om de kleur en het feestelijke karakter te temperen. Wat begon als een sober rouwdrankje groeide uit tot een gewaardeerde combinatie op zich, nog altijd geserveerd bij feestelijke gelegenheden ondanks de sombere oorsprong. Vertel je gasten dat deze mix van champagne en stout letterlijk is ontstaan uit nationale rouw, niet uit feestvreugde.",
  aperol_spritz: "De spritz ontstond in de negentiende eeuw in het Noord-Italiaanse Veneto, dat toen bij Oostenrijk hoorde. Oostenrijkse soldaten vonden de lokale wijn te zwaar en spoten er water bij ('spritzen' in het Duits, vandaar de naam). Aperol zelf werd pas in 1919 geïntroduceerd door de gebroeders Barbieri in Padua. De combinatie met prosecco en bruiswater werd pas na 2003 een wereldhit, toen Campari Group het merk kocht en wereldwijd promootte. Vertel je gasten dat de oranje drank die nu op elk terras staat als wereldhit dus pas van na 2000 is.",
  pina_colada: "Uitgevonden in 1954 (of daaromtrent) door barman Ramón 'Monchito' Marrero in het Caribe Hilton hotel in San Juan, Puerto Rico, die naar verluidt drie maanden experimenteerde voordat hij de perfecte balans tussen rum, ananas en kokosroom vond. Sinds 1978 is het officieel de nationale cocktail van Puerto Rico, verankerd bij wet. De introductie van cream of coconut (een kant-en-klaar kokosroomproduct) rond diezelfde tijd maakte de cocktail pas echt haalbaar voor bars wereldwijd. Vertel je gasten dat zonder die uitvinding de Piña Colada waarschijnlijk nooit de wereldwijde hit was geworden die hij nu is.",
  mai_tai: "Bedacht in 1944 door Victor 'Trader Vic' Bergeron in Oakland, Californië, en meteen onderwerp van een decennialange ruzie met zijn rivaal Donn Beach (Don the Beachcomber) over wie de cocktail nu echt had uitgevonden. Volgens Trader Vic's eigen, veelverteld verhaal proefde een Tahitiaanse vriendin de allereerste versie en riep spontaan 'Maita'i roa ae!', Tahitiaans voor 'het beste er is!', wat de naam werd. De cocktail leunt zwaar op ouder, complexer gerijpte rum en oranjelikeur, in tegenstelling tot veel latere, simpelere tiki-drankjes. Vertel je gasten dat de originele Mai Tai van Trader Vic bewust géén ananassap of grenadine bevatte. De zoetige, felgekleurde versies die je nu vaak ziet zijn latere, versimpelde afgeleiden.",
  bramble: "Bedacht in 1984 door de Britse barman Dick Bradsell in Londen, dezelfde man achter de Espresso Martini en de Russian Spring Punch, geïnspireerd door zijn jeugdherinneringen aan het plukken van bramen in de Britse velden. De cocktail bestaat uit een simpele gin-citroen-basis met een laagje braambessenlikeur die er, in plaats van doorgeroerd, overheen wordt gedruppeld zodat het als een 'bloedende' streep door de drank zakt. Vertel je gasten dat die druipende, gelaagde look expres zo wordt geserveerd. Nooit doorroeren, dat is precies het visuele handelsmerk van de cocktail.",
  zombie: "Bedacht in de jaren '30 door Donn Beach (Don the Beachcomber), de grondlegger van de Amerikaanse tiki-cultuur, die het originele recept zo geheim hield dat hij zijn barpersoneel de ingrediënten liet mengen uit ongelabelde, genummerde flessen om spionage door concurrenten te voorkomen. De naam zou zijn ontstaan doordat een klant, na het drinken van er twee, de volgende dag terugkwam en klaagde dat hij zich als een 'levende dode' voelde. Met soms wel vijf verschillende soorten rum is het een van de sterkste en complexste tiki-cocktails ooit bedacht. Vertel je gasten dat Donn Beach zijn eigen recept decennialang niet eens aan zijn eigen personeel volledig prijsgaf.",
  chartreuse_swizzle: "Een moderne klassieker, bedacht rond 2002 door barman Marcovaldo Dionysos in San Francisco, rond groene Chartreuse. Die kruidenlikeur wordt gemaakt door kartuizer monniken in Frankrijk, naar een recept met 130 planten dat teruggaat op een manuscript uit 1605. Slechts twee monniken tegelijk kennen het volledige recept. De 'swizzle'-techniek, een stokje snel ronddraaien in fijngestampt ijs, komt uit het Caribisch gebied en maakt de drank ijskoud en fris. Vertel je gasten dat ze een drank drinken op basis van een eeuwenoud kloosterrecept dat nog steeds geheim is.",
  illegal: "Een moderne mezcalcocktail, genoemd naar het merk Ilegal Mezcal. Dat merk begon met de Amerikaan John Rexer, die voor zijn bar in Guatemala mezcal uit Oaxaca over de grens smokkelde, omdat hij het niet legaal kon invoeren. Mezcal, overproof rum, falernum, maraschino en limoen: rokerig met een tropische toets. Sinds 2020 staat de cocktail op de officiële lijst van de International Bartenders Association, en hij hoort bij de golf mezcalcocktails die sinds de jaren 2010 de wereld over ging.",
  jungle_bird: "Bedacht in 1978 in het Aviary Bar van het Kuala Lumpur Hilton in Maleisië, een van de weinige beroemde tiki-cocktails die niet in Amerika is ontstaan. Wat de cocktail uniek maakt binnen de tiki-familie is het gebruik van Campari, een Italiaanse bittere likeur die zelden in tropische rum-drankjes wordt gebruikt, wat de Jungle Bird een verrassend bittere tegenhanger geeft binnen een verder zoet-fruitig genre. Decennialang vergeten, tot de cocktail rond 2010 door de craft-cocktailbeweging werd herontdekt en alsnog een moderne klassieker werd.",
  missionarys_downfall: "Een van de originele Donn Beach-recepten uit de jaren '30/'40, met een veelbetekenende naam: de suggestie dat zelfs de meest principiële zendeling ('missionary') door dit drankje van het rechte pad zou worden gebracht. Munt, perzik en rum in een fijngestampte ijsdrank maken 'm ongewoon fris en fruitig binnen het vaak zwaardere tiki-genre. Zoals bij veel Donn Beach-recepten bleef de exacte receptuur decennialang verloren tot cocktailhistorici het pas recent wisten te reconstrueren.",
  iba_tiki: "Een nieuwe tiki-cocktail, bedacht in 2022 door de Cubaanse barman Diosmel Mendoza Medrano en sinds 2024 opgenomen in de officiële lijst van de International Bartenders Association (IBA). Die organisatie houdt een lijst bij van erkende klassieke en moderne cocktails, met vaste recepten voor wedstrijden en barscholen. Deze cocktail combineert twee soorten rum met amaretto, Frangelico, passievrucht, ananas en limoen. Vertel je gasten dat dit een van de nieuwste cocktails is die het tot de officiële lijst heeft geschopt.",
  three_dots_and_a_dash: "Een van de meest gedetailleerde en tijdrovende tiki-cocktails ooit bedacht door Donn Beach, genoemd naar het morsecodeteken voor de letter 'V', een eerbetoon aan de Victory (overwinning) tijdens de Tweede Wereldoorlog. De originele garnering bestond letterlijk uit drie cocktailkersen en één ananasreep om het morsesymbool visueel na te bootsen op de cocktailprikker. Vertel je gasten dat de garnering hier geen decoratie is maar een verborgen boodschap: letterlijk morsecode voor 'overwinning'.",
  blue_hawaiian: "Bedacht in 1957 door barman Harry Yee in het Hilton Hawaiian Village op Waikiki Beach, die ook de eerste was die een orchidee als cocktailgarnering gebruikte en de paraplu-prikker populair maakte in tiki-bars. Blauwe curaçao geeft de cocktail zijn karakteristieke, felblauwe 'oceaan'-kleur. Puur decoratief, zonder dat het de smaak veel beïnvloedt, maar essentieel voor het Instagram-voor-de-uitvinding-van-Instagram-effect dat tiki-bars altijd hebben nagestreefd.",
  hurricane: "Bedacht in de jaren '40 door Pat O'Brien, eigenaar van een bar in New Orleans, die van zijn drankleverancier verplicht een overschot aan rum moest afnemen om schaarsere whiskey te mogen kopen tijdens een naoorlogs drankentekort. Om van die rum af te komen bedacht hij een zoete, fruitige cocktail geserveerd in een glas gevormd als een hurricanelamp, vandaar de naam. Tegenwoordig is het onlosmakelijk verbonden met het jaarlijkse Mardi Gras-feest in New Orleans, waar het bij duizenden tegelijk wordt geschonken.",
  painkiller: "Bedacht in de jaren '70/'80 door Daphne Henderson in de Soggy Dollar Bar op Jost Van Dyke, een eilandje in de Britse Maagdeneilanden dat zo klein en afgelegen is dat bezoekers er letterlijk vanaf hun boot naartoe moesten zwemmen. Vandaar de bijnaam 'Soggy Dollar' (natte dollar) voor het nog vochtige geld waarmee mensen betaalden. Pusser's Rum, het merk dat de bar bevoorraadde, claimde later het handelsmerk op de naam 'Painkiller', vergelijkbaar met wat Gosling's deed met de Dark 'n' Stormy. Vertel je gasten dat deze cocktail is uitgevonden op een bar die je alleen zwemmend kon bereiken.",
  scorpion: "Een van Trader Vic's eigen tiki-creaties uit de jaren '40, traditioneel geserveerd in een grote, deelbare kom met meerdere rietjes voor een hele groep, een vroeg voorbeeld van het 'sharing punch'-concept dat tiki-bars later tot een kunstvorm zouden verheffen met steeds extravagantere serveerschalen. De combinatie van rum, brandy en amandelsiroop (orgeat) geeft de drank een rijke, nootachtige diepte die 'm onderscheidt van lichtere tiki-cocktails.",
  navy_grog: "Geïnspireerd op het historische rantsoen van de Britse Koninklijke Marine, die vanaf 1740 op bevel van admiraal Edward Vernon, bijgenaamd 'Old Grog' vanwege zijn mantel van grogram-stof, de dagelijkse rumrantsoen van matrozen verplicht met water moest verdunnen om dronkenschap aan boord te beperken. Donn Beach herwerkte dat sobere marinerantsoen decennia later tot een weelderige tiki-cocktail met drie soorten rum, wat de oorspronkelijke, ontnuchterende bedoeling van de 'grog' compleet op zijn kop zet. Vertel je gasten dat 'grog' dus oorspronkelijk juist bedoeld was om matrozen minder dronken te maken, niet meer.",
  penicillin: "Bedacht in 2005 door de Australische bartender Sam Ross in New York, en binnen enkele jaren een van de meest nagemaakte moderne klassiekers ter wereld, een prestatie die maar weinig eenentwintigste-eeuwse cocktails hebben geëvenaard. De ironische naam ('penicilline') verwijst naar de honing-gember-citroen-basis die aan een warme verkoudheidsremedie doet denken, terwijl een drijflaag rokerige Islay-scotch bovenop juist een intense, rokerige tegenstelling geeft. Vertel je gasten dat de rokerige laag bovenop expres nooit wordt doorgeroerd. Elke slok begint rokerig aan de bovenkant en wordt zoeter en kruidiger naarmate je dieper in het glas komt.",
  paper_plane: "Bedacht in 2007 door de Australische bartender Sam Ross (ook bedenker van de Penicillin) voor de bar The Violet Hour in Chicago, en genoemd naar het nummer 'Paper Planes' van M.I.A., dat hij toen steeds draaide. In de eerste versie zat Campari; later werd het Aperol. De cocktail bestaat uit precies gelijke delen bourbon, Aperol, Amaro Nonino en citroensap: een perfect gebalanceerde opbouw zonder één dominant ingrediënt. Binnen een paar jaar werd hij een van de meest bestelde moderne cocktails.",
  naked_and_famous: "Bedacht in 2011 door de Amerikaanse bartender Joaquín Simó in de New Yorkse bar Death & Co. Hij noemde het zelf 'het liefdeskind van de Last Word en de Paper Plane, verwekt in de bergen van Oaxaca': vier ingrediënten in gelijke delen, met mezcal, gele Chartreuse, Aperol en limoensap. Waar de naam vandaan komt, wordt verschillend verteld; meestal wordt een liedje met die titel genoemd. Rokerig, kruidig en bitter tegelijk: een van de mooiste evenwichtsoefeningen uit de moderne cocktailwereld.",
  last_word: "Ontstaan rond 1916 in de Detroit Athletic Club, tijdens de Amerikaanse drooglegging vrijwel in de vergetelheid geraakt, en pas in 2004 herontdekt door barman Murray Stenson in Seattle nadat hij het recept toevallig tegenkwam in een oud, stoffig barboek. Binnen enkele jaren na die herontdekking werd de Last Word, gelijke delen gin, groene Chartreuse, maraschino-likeur en limoensap, een van de meest gerespecteerde 'nieuwe oude' klassiekers van de eenentwintigste eeuw. Vertel je gasten dat deze cocktail letterlijk bijna een eeuw verdwenen is geweest voordat hij zijn huidige roem verwierf.",
  corpse_reviver_2: "De beroemdere, gin-gebaseerde broer van de Corpse Reviver #1, gepubliceerd in Harry Craddocks Savoy Cocktail Book van 1930 met de veelgeciteerde waarschuwing: 'Four of these taken in swift succession will unrevive the corpse again', vier van deze snel achter elkaar zullen het lijk juist weer om zeep helpen. Bedoeld als kater-genezend ochtenddrankje voor de Britse high society, combineert het gin, Lillet Blanc, triple sec, citroen en een zweem absint. Vertel je gasten Craddocks eigen waarschuwing voordat ze een tweede bestellen.",
  pisco_punch: "Pisco Punch werd vanaf de jaren 1850 geschonken in de Bank Exchange Saloon in San Francisco, in de tijd dat de stad door de goudkoorts volstroomde met fortuinzoekers. Beroemd werd hij door Duncan Nicol, die de bar vanaf de jaren 1880 runde. Nicol hield zijn recept zo geheim dat het na de sluiting van de bar tijdens de drooglegging en zijn dood in 1926 grotendeels verloren ging. Pas later is het met vallen en opstaan gereconstrueerd uit oude aantekeningen. Vertel je gasten dat ze een drank drinken waarvan het originele recept lang als verloren gold.",
  alexander: "Een dessertcocktail uit het begin van de twintigste eeuw, met gin, crème de cacao en room. Het bekendste verhaal noemt barman Troy Alexander van het New Yorkse restaurant Rector's, rond 1915; andere verhalen noemen een Russische tsaar of de journalist Alexander Woollcott. De latere variant met cognac (de Brandy Alexander) verdrong de gin-versie zo grondig dat de meeste mensen niet eens weten dat die bestond.",
  white_russian: "Ontstaan in de jaren '60 als variant op de Black Russian, en wereldberoemd geworden dankzij de cultfilm \"The Big Lebowski\" uit 1998, waarin hoofdpersonage 'The Dude' er in bijna elke scène een in zijn hand heeft. Ondanks de naam heeft de cocktail geen Russische oorsprong. 'Russisch' verwijst simpelweg naar de wodka, een gewoonte in veel Koude Oorlog-tijdperk cocktailnamen. Vertel je gasten dat de populariteit van deze cocktail vandaag de dag vrijwel volledig aan één filmpersonage te danken is, decennia na de eigenlijke uitvinding.",
  black_russian: "Bedacht in 1949 door de Belgische barman Gustave Tops in het Hotel Metropole in Brussel, ter ere van Perle Mesta, de Amerikaanse ambassadeur in Luxemburg. Vandaar de link met de 'Koude Oorlog'-stijl naamgeving rond wodka. Simpelweg wodka met koffielikeur, zonder de latere toevoeging van room die de White Russian zou onderscheiden. Vertel je gasten dat dit dus het origineel is: de White Russian kwam pas later, als 'zachtere' variant.",
  brandy_alexander: "De cognac-versie van de Alexander die de originele gin-uitvoering in populariteit ver overtrof, vooral nadat de cocktail in de jaren '70 een geliefd na-dinerdrankje werd bij een publiek dat room en chocolade-achtige smaken prefereerde boven de kruidigere gin-versie. John Lennon zou er tijdens zijn beruchte 'verloren weekend' in Los Angeles in de jaren '70 overdadig veel van hebben gedronken, een anekdote die de cocktail nog altijd een vleugje rock-'n-roll-glamour geeft.",
  grasshopper: "Uitgevonden in 1918 door Philibert Guichet, eigenaar van Tujague's, een van de oudste restaurants van New Orleans, voor een cocktailwedstrijd in New York. Hij eindigde als tweede, maar zijn drankje werd alsnog wereldberoemd. De felgroene kleur, afkomstig van crème de menthe, zou de naam ('sprinkhaan') hebben ingegeven. Decennialang een populair, kitscherig dessertdrankje in Amerikaanse steakhouses, tegenwoordig meer nostalgie dan trend.",
  mudslide: "Ontstaan in de jaren '70 op de Cayman Islands, in een bar genaamd The Wreck Bar, als een romige, dessertachtige cocktail op basis van wodka, koffielikeur en Ierse room-likeur (Baileys). De naam ('modderlawine') verwijst gewoon naar de bruinige, dikke textuur van de drank. Werd in de jaren '80-'90 razend populair in Amerikaanse restaurantketens, vaak zelfs als bevroren, slush-achtige variant geserveerd.",
  toasted_almond: "Een romige jaren-'70-'80-dessertcocktail op basis van amaretto en koffielikeur met melk of room, onderdeel van dezelfde golf 'na-dinerdrankjes' als de Mudslide en Grasshopper die destijds populair waren in Amerikaanse restaurants als alternatief voor een gewoon dessert. De naam verwijst naar de geroosterde-amandelsmaak die amaretto van nature meebrengt.",
  golden_cadillac: "Ontstaan in de jaren '50 in Amerika, gemaakt met Galliano, een felgele, kruidige Italiaanse likeur genoemd naar majoor Giuseppe Galliano, een Italiaanse legerheld uit de Eerste Italiaans-Ethiopische Oorlog, gecombineerd met crème de cacao en room. De naam verwijst naar de gouden kleur en naar de Cadillac als statussymbool van Amerikaanse welvaart in die jaren, precies het gevoel dat deze weelderige, romige cocktail moest oproepen.",
  golden_dream: "Een jaren-'60-cocktail eveneens gebouwd op Galliano, ditmaal gecombineerd met triple sec, sinaasappelsap en room tot een zoete, gouden dessertdrank, vernoemd naar dezelfde gouden kleur die Galliano aan zoveel cocktails uit die periode gaf. Onderdeel van een hele familie 'Golden'-cocktails die in de jaren '60-'70 de likeur wereldwijd op de kaart zetten, ver voordat Galliano decennia later weer bijna in de vergetelheid raakte.",
  chocolate_martini: "Een typische jaren-'90-creatie uit dezelfde golf als de Apple Martini en Lychee Martini, waarbij chocoladelikeur of crème de cacao met wodka wordt gecombineerd en in een martiniglas geserveerd puur vanwege de glamoureuze uitstraling van dat glas, zonder verdere link naar de klassieke, droge Martini. Vaak afgewerkt met een cacaorand op het glas voor extra chocolade-effect bij elke slok.",
  harvey_wallbanger: "Een Screwdriver met een drijflaag Galliano erop, vermoedelijk uit de jaren '50 of '60 in Californië. Het verhaal wil dat een surfer genaamd Harvey er na een verloren wedstrijd zoveel van dronk dat hij tegen de muren van de bar botste ('wall-banging'), maar dat verhaal is waarschijnlijk achteraf bedacht. In de jaren '70 maakte Galliano er een grote reclamecampagne van met een getekende mascotte, Harvey, en werd de cocktail overal in Amerika gedronken.",
  irish_coffee: "Bedacht in 1943 door chef-kok Joe Sheridan op de luchthaven van Foynes, Ierland, om onderkoelde Amerikaanse passagiers op te warmen wier vliegboot vanwege slecht weer was teruggekeerd naar de startbaan. Sheridan mengde whiskey door de koffie en voegde room toe. Een reiziger zou hem vervolgens hebben gevraagd of dit 'Braziliaanse koffie' was, waarop Sheridan antwoordde: 'nee, dat is Ierse koffie.' De cocktail bereikte pas echt wereldfaam nadat een Amerikaanse journalist het recept in San Francisco liet namaken bij café Buena Vista, dat het tot op vandaag nog altijd serveert. Vertel je gasten dat de room er drijvend bovenop moet blijven liggen, nooit doorgeroerd. Je drinkt de warme koffie eronderdoor terwijl de koude room je lippen raakt.",
  hot_toddy: "Een van de oudste 'medicinale' mixdrankjes: warme sterke drank met honing, citroen en kruidnagel, al eeuwenlang een volksmiddel tegen verkoudheid in Schotland en Ierland. De naam komt waarschijnlijk van 'taddy', een drank van gegist palmsap uit India die Britten in de zeventiende eeuw leerden kennen. Een ander verhaal noemt Tod's Well, een bron in Edinburgh, maar dat is minder waarschijnlijk. Vertel je gasten dat de moderne Penicillin-cocktail op precies hetzelfde idee voortbouwt: honing, citroen, gember en whisky tegen een verkoudheid.",
  virgin_mojito: "De alcoholvrije versie van de Cubaanse Mojito, waarbij de rum simpelweg wordt weggelaten en vaak vervangen door extra sodawater of limonade. Precies dezelfde munt-limoen-suiker-basis die de Mojito al eeuwenlang zijn frisheid geeft, blijft intact. Steeds vaker standaard op menukaarten sinds de jaren 2010, toen de vraag naar volwaardige alcoholvrije cocktails (in plaats van alleen frisdrank) wereldwijd flink toenam.",
  virgin_mule: "De alcoholvrije versie van de Moscow Mule, met gemberbier en limoen maar zonder de wodka, geserveerd in dezelfde koperen beker als het origineel uit 1941, wat laat zien hoe sterk de visuele identiteit van een cocktail soms los kan staan van de alcohol zelf. Een goed voorbeeld van hoe moderne bars steeds vaker complete, serieuze alcoholvrije varianten van klassiekers ontwikkelen in plaats van gasten simpelweg naar cola te verwijzen.",
  shirley_temple: "Genoemd naar de gelijknamige Amerikaanse kindsterractrice uit de jaren '30, die naar verluidt zelf niet dol was op de cocktail die haar naam draagt. Ze zou later in interviews hebben gezegd dat ze de zoete drank eigenlijk maar niets vond. Gemaakt met ginger ale en grenadine, geserveerd met een maraschinokers, werd het decennialang hét standaarddrankje voor kinderen aan de bar terwijl de volwassenen iets sterkers dronken. Vertel je gasten deze ironie: de beroemdste alcoholvrije 'kindercocktail' ter wereld is genoemd naar een kind dat 'm zelf niet lekker vond.",

  // ===== AANVULLING: klassiekers uit de index van "The Cocktail Bible" =====
  army_and_navy: "Een klassieker die al in 1948 in David Embury's invloedrijke boek \"The Fine Art of Mixing Drinks\" staat, en die de afgelopen jaren door bars als Death & Co in New York weer op de kaart is gezet. In feite een gin sour waarin amandelsiroop (orgeat) de suiker vervangt, wat de drank een zachtere, nootachtige body geeft. De naam verwijst waarschijnlijk naar de jaarlijkse footballwedstrijd tussen de Amerikaanse leger- en marineacademies, al is dat niet zeker.",
  applejack_sour: "Gebouwd op applejack, gedistilleerd appelbrandewijn en daarmee een van de oudste Amerikaanse sterkedranken: kolonisten in New Jersey distilleerden het al in de achttiende eeuw uit hun appeloverschot, ruim voordat whiskey de dominante Amerikaanse spirit werd. Laird's, nog altijd de bekendste producent, claimt een ononderbroken productie sinds 1780. Vertel je gasten dat zij hiermee letterlijk ouder Amerikaans erfgoed proeven dan bourbon.",
  avondale_habit: "Een eenvoudige sour van cognac, crème de menthe en citroen. Over de herkomst is weinig bekend. Het idee is wel herkenbaar: cognac met munt kennen we van de Stinger, het klassieke na-dinerdrankje uit de jaren 1890. Met citroen erbij wordt die combinatie een stuk frisser en lichter.",
  blinker: "Een cocktail uit de tijd van de drooglegging, opgenomen in Patrick Gavin Duffy's \"Official Mixer's Manual\" uit 1934, met rye whiskey, grapefruitsap en grenadine. Grapefruit kwam in cocktails uit die tijd minder voor dan citroen of limoen, wat hem een eigen, bitterzoet karakter geeft. Moderne bartenders maken hem vaak met frambozensiroop in plaats van grenadine.",
  cairprioska: "De wodka-versie van de Braziliaanse Caipirinha, ontstaan doordat cachaça buiten Brazilië lange tijd moeilijk verkrijgbaar was terwijl wodka overal voorradig stond. Bartenders en thuisdrinkers substitueerden simpelweg de basis maar hielden de muddel-limoen-techniek intact. Vertel je gasten dat dit een van de duidelijkste voorbeelden is van hoe een cocktailformule (hier: gemuddelde limoen plus suiker plus sterkedrank) losstaat van één specifieke spirit.",
  champs_elysees: "Opgenomen in Harry Craddocks Savoy Cocktail Book uit 1930, genoemd naar de beroemde Parijse boulevard, in een tijd dat Amerikaanse bartenders tijdens de drooglegging massaal naar Parijse bars uitwoken en Franse namen en ingrediënten (hier: cognac en groene Chartreuse) in de mode kwamen. De combinatie van cognac met de kruidige, sterke Chartreuse-likeur van Franse kartuizermonniken geeft de drank een ongewoon diepe, kruidige body voor een sour.",
  coconut_daiquiri: "Een moderne, tropische variant op de Cubaanse Daiquiri, waarbij kokosroom de suikersiroop deels vervangt voor een voller, romiger mondgevoel. Onderdeel van de brede familie fruit-Daiquiri's die sinds de jaren '30 (met de Hemingway-versie als beroemdste voorbeeld) is ontstaan door telkens één nieuw element aan de kernformule rum-limoen-zoet toe te voegen.",
  desert_daisy: "Onderdeel van de negentiende-eeuwse Amerikaanse 'Daisy'-familie (Brandy Daisy, Whiskey Daisy), cocktails met een basis-sterkedrank, citrus, een zoetmiddel en vaak een likeurtje als accent. Deze tequila-versie is een latere, twintigste-eeuwse toevoeging aan die familie, ontstaan toen tequila vanaf de jaren '30-'40 langzaam de Amerikaanse bar binnenkwam. Vertel je gasten dat de 'Daisy'-structuur later rechtstreeks de basis vormde voor de Margarita.",
  eve: "Een sour van cognac, triple sec en citroen met een paar druppels absint. De naam verwijst waarschijnlijk speels naar de verboden vrucht: absint was vanaf de jaren 1910 in veel landen verboden, en hier zit er net genoeg in voor een 'verboden' accent.",
  golden_sour: "Een moderne bourbon-sour met honing in plaats van suikersiroop, een variant die sinds de craft-cocktailrevival van de jaren 2000 populair werd toen bartenders massaal terugkeerden naar natuurlijke zoetmiddelen. De 'gouden' kleur komt van de combinatie van bourbon en honing samen.",
  harlequin: "Een minder bekende klassieker uit de vroege twintigste eeuw, met een naam die verwijst naar de kleurrijke harlekijn-figuur uit de Italiaanse commedia dell'arte, wellicht een knipoog naar de kleurcombinatie van gin en abrikozenlikeur. Een eenvoudige, weinig gedocumenteerde maar smakelijke sour uit dezelfde periode als veel Savoy Cocktail Book-recepten.",
  ivy_gimlet: "Een moderne twist op de klassieke Gimlet, genoemd naar The Ivy, het beroemde Londense restaurant en besloten club waar acteurs en schrijvers al sinds 1917 komen. Vlierbloesemsiroop in plaats van suikersiroop geeft de klassieke gin-limoen-formule een bloemige, Britse twist die past bij de elegante reputatie van de naamgever.",
  kiwi_smash: "Onderdeel van de 'Smash'-familie, een format dat teruggaat tot Jerry Thomas' allereerste Amerikaanse barboek uit 1862: gemuddeld fruit met een sterkedrank, citrus en suiker. Kiwi is een latere, twintigste-eeuwse toevoeging aan die eeuwenoude formule, onderdeel van de golf fruit-smashes die met de opkomst van moderne cocktailbars steeds exotischer werd.",
  machete: "Een moderne, Mexicaans geïnspireerde tequila-cocktail met een naam die rechtstreeks verwijst naar het gereedschap dat onmisbaar is bij de agave-oogst voor tequila. Munt en limoen geven de drank een frisse, bijna Mojito-achtige twist op de klassieke tequila-sour-formule.",
  nevada_cocktail: "Een Prohibition-tijdperk rum-sour met een scheutje grapefruitsap en Angostura, opgenomen in verschillende Amerikaanse en Britse barboeken uit de jaren '30. De naam verwijst simpelweg naar de Amerikaanse staat, zonder dat er een specifiek verhaal over de oorsprong bekend is, typisch voor veel drankjes uit die periode die gewoon een klinkende Amerikaanse plaatsnaam meekregen.",
  orange_blossom: "Ontstaan tijdens de Amerikaanse drooglegging (1920-1933), toen bathtub gin vaak zo ruw en onaangenaam smaakte dat bartenders 'm verplicht moesten maskeren met flink wat sinaasappelsap en suiker. Zodra na 1933 weer legale, kwalitatieve gin beschikbaar kwam, verloor de cocktail grotendeels zijn functie en raakte hij op de achtergrond. Vertel je gasten dat dit een mooi voorbeeld is van een cocktail die is ontstaan uit noodzaak (slechte drank verdoezelen), niet uit puur creatief plezier.",
  perfect_lady: "Opgenomen in Harry Craddocks Savoy Cocktail Book uit 1930, met gin, perzikschnapps, citroen en eiwit voor een zachte, romige textuur. De naam past in een trend van die tijd om lichtere, fruitigere cocktails specifiek te profileren als 'geschikt voor dames', een marketingconventie die inmiddels flink gedateerd aanvoelt maar destijds gangbaar was.",
  queen_mother_cocktail: "Een modernere klassieker, populair geworden via Londense cocktailbars in de jaren 2000, met een speelse verwijzing naar de Britse Queen Mother, bekend om haar liefde voor een goed glas gin. Braambessenlikeur geeft de klassieke gin-sour-formule een donkerpaarse kleur en een iets rijkere smaak.",
  red_cloud: "Een Prohibition-tijdperk gin-sour met abrikozenlikeur en grenadine, opgenomen in verschillende Amerikaanse barboeken uit de jaren '20-'30. De naam verwijst mogelijk naar Red Cloud, de bekende Lakota-Sioux-leider uit de negentiende eeuw, al is een directe historische link met de cocktail zelf niet vastgelegd.",
  rhett_butler: "Genoemd naar het hoofdpersonage uit \"Gone with the Wind\" (roman 1936, film 1939). Een sour met bourbon, triple sec, limoen en een beetje cranberry. Vaak wordt hij met Southern Comfort gemaakt, een likeur uit het zuiden van de VS, waar het verhaal zich afspeelt. Een voorbeeld van hoe een populaire film een cocktailnaam kan opleveren.",
  rum_sour: "De rum-toepassing van de klassieke sour-formule (sterkedrank, citrus, zoetmiddel) die teruggaat tot de negentiende eeuw, toen elke basis-sterkedrank zijn eigen 'sour'-variant kreeg. Waar de Daiquiri de bekendste, verfijndere rum-sour werd, bleef de gewone Rum Sour de simpelere, minder geraffineerde huisgenoot.",
  sloe_gin_sour: "Sloe gin, gemaakt door sleedoornbessen (kleine, wrange wilde pruimen) te laten trekken in gin met suiker, is een negentiende-eeuwse Engelse plattelandstraditie, oorspronkelijk vaak zelfgemaakt na de sleedoornoogst in de herfst. Deze sour-toepassing combineert die rustieke, fruitige likeur met de klassieke citrus-suiker-balans.",
  southside: "Een gin-sour met munt, waarvan de oorsprong wordt betwist tussen twee heel verschillende verhalen: de Southside Sportsmen's Club, een deftige jacht- en visclub op Long Island, of de bende van Al Capone aan de South Side van Chicago. Beide verhalen zijn niet bewezen, wat de Southside een van de weinige cocktails maakt met twee totaal tegengestelde oorsprongsverhalen.",
  strawberry_mint_daiquiri: "Een fruitige, moderne Daiquiri-variant met gemuddelde aardbei en munt, onderdeel van de brede familie fruit-Daiquiri's die vanaf de jaren '30 (met de Hemingway-versie als beroemdste voorbeeld) telkens één nieuw vers element aan de kernformule rum-limoen-suiker toevoegde.",
  vanilla_fix: "Onderdeel van de 'Fix'-familie, een negentiende-eeuws Amerikaans format dat al in Jerry Thomas' allereerste barboek van 1862 voorkomt: een sterkedrank met citrus en zoetmiddel, geserveerd over fijngestampt ijs. Vanille is een latere, twintigste-eeuwse toevoeging aan dat eeuwenoude sjabloon.",
  vodka_sour: "De wodka-toepassing van de klassieke sour-formule, die in Amerika vooral vanaf de jaren '50-'60 aan populariteit won toen wodka (mede dankzij de Moscow Mule) de dominante 'neutrale' basis-sterkedrank werd voor bartenders die klanten geen uitgesproken smaakprofiel wilden opdringen.",
  xyz_cocktail: "Een cocktail uit het Savoy Cocktail Book van 1930, met een naam waarvan de herkomst onbekend is: misschien gewoon een knipoog naar het einde van het alfabet. In feite een rum-Sidecar: dezelfde opbouw met triple sec en citroen, maar met rum in plaats van cognac.",
  french_kiss: "Een moderne cognac-cocktail met perzik en ananas, met een speelse, romantische naam die past bij de bredere trend van suggestieve cocktailnamen in eigentijdse cocktailkaarten. Geen gedocumenteerde specifieke oorsprong, wel een smakelijke illustratie van hoe cognac zich prima laat combineren met tropisch fruit.",
  honolulu: "Een vroeg twintigste-eeuwse gin-sour met een tropische naam, uit een periode waarin Hawaï net in de Amerikaanse verbeelding begon te leven (ruim vóór de latere tiki-golf van de jaren '30-'50) en 'exotische' plaatsnamen al genoeg waren om een cocktail een avontuurlijk imago te geven, ook zonder daadwerkelijk Hawaiiaanse ingrediënten.",
  infante: "Een moderne tequilacocktail; 'infante' is Spaans voor een prins of prinses van koninklijken bloede. Deze versie combineert tequila met kruidige groene Chartreuse, grapefruit en limoen, in lijn met de trend om tequila serieuzer en complexer te behandelen dan als shotje. Let op: de bekendste Infante, van de New Yorkse barman Giuseppe González, is een andere drank, met orgeat, nootmuskaat en rozenwater.",
  passion_fruit_margarita: "Een moderne uitbreiding op de klassieke Margarita, ontstaan toen passievrucht in de jaren 2000-2010 een van de meest gebruikte tropische smaken in westerse cocktailbars werd. Dezelfde zout-citrus-tequila-basis als het origineel, met een geurige, zurige twist erbovenop.",
  rude_cosmopolitan: "Een speelse, moderne twist op de jaren-'90-klassieker Cosmopolitan, waarbij tequila de wodka vervangt. De naam ('onbeschofte' Cosmopolitan) verwijst luchtig naar hoe deze versie zich niets aantrekt van het origineel en zijn eigen, stevigere basis-sterkedrank kiest.",
  south_of_the_border: "Een moderne tequila-cocktail met koffielikeur, met een naam die (vanuit Amerikaans perspectief) simpelweg 'Mexico' betekent. De combinatie van agave-sterkedrank met koffie-bitterzoet is een minder voor de hand liggende, maar verrassend goed werkende pairing.",
  doobs_martini: "Een extreem droge Martini: 70 ml gin tegen slechts 5 ml vermout, met een druppel sinaasappelbitters. Die stijl is beroemd geworden door Dukes Bar in Londen, waar de Martini aan een trolley naast je tafel wordt gemaakt met ijskoude gin en nauwelijks een zweem vermout. Waar de naam 'Doobs' vandaan komt, is niet bekend.",
  vodka_gibson: "De wodka-versie van de klassieke Gibson (gin met droge vermout en een cocktailui), ontstaan toen wodka vanaf de jaren '60 steeds vaker de rol van gin overnam in klassieke Martini-achtige cocktails voor drinkers die een neutralere basis prefereerden.",
  london_calling: "Een moderne Britse cocktail, bedacht in 2002 door Chris Jepson in de Londense bar Milk & Honey, en vernoemd naar het nummer en album van The Clash uit 1979. Hij combineert gin met droge sherry, een combinatie die populair werd toen bartenders sherry weer serieus gingen nemen als cocktailingrediënt. Het origineel is een sour met citroen; deze versie in de app is geroerd, met droge vermout en bitters.",
  yale_cocktail: "Een vroeg twintigste-eeuwse, Amerikaans-collegiaal genoemde cocktail (net als de Harvard Cocktail), met blauwe curaçao die de drank de karakteristieke blauwe kleur van Yale University geeft. Een goed voorbeeld van hoe Amerikaanse universiteiten ooit hun eigen cocktail-eer nastreefden via de kleur van hun huisstijl.",
  los_altos: "Genoemd naar Los Altos de Jalisco, de bergachtige hooglandregio in Mexico die geldt als een van de twee klassieke terroirs voor tequila (naast het lager gelegen 'Valle'-gebied). Deze stirred-down cocktail behandelt tequila met dezelfde égards als gin in een Martini, droge vermout en al.",
  new_orleans_dry_martini: "Een Martini-variant met een absint-scheutje, een knipoog naar de New Orleans-cocktailtraditie waar absint al sinds de negentiende eeuw een vaste rol speelt (denk aan de Sazerac). Hetzelfde principe als de klassieke Martini, maar met een subtiel kruidig-anijsachtig randje.",
  little_italy: "Een moderne New Yorkse klassieker, bedacht rond 2005 door Audrey Saunders in haar bar Pegu Club, en genoemd naar de Italiaanse buurt in Manhattan. In feite een Manhattan met een scheut Cynar, een bittere Italiaanse amaro op basis van artisjok, die de drank een aardse diepte geeft.",
  grappa_manhattan: "Een Italiaanse twist op de klassieke Amerikaanse Manhattan, waarbij grappa (Italiaanse druivenschillen-brandewijn) de whiskey vervangt. Onderdeel van een bredere trend waarbij bartenders de simpele, herbruikbare Manhattan-formule (sterkedrank, zoete vermout, bitters) telkens met een andere basis-spirit combineren.",
  italian_heather: "Een speelse fusie-naam voor een cocktail die Schotse scotch combineert met de honing-kruiden-likeur Drambuie (zelf al een Schotse klassieker in de Rusty Nail), aangevuld met zoete vermout voor een Italiaans accent. Een moderne illustratie van hoe klassieke nationale ingrediënten zich laten combineren tot iets nieuws.",
  inspiration: "Een minder bekende, vroeg twintigste-eeuwse stirred-down cocktail met gin, Bénédictine en droge vermout, in dezelfde stijl en periode als veel Savoy Cocktail Book-recepten. De vage, positieve naam past in een trend van die tijd om cocktails simpelweg een aangenaam gevoel te laten uitstralen zonder concreet verhaal.",
  kiss_in_the_dark: "Opgenomen in Harry Craddocks Savoy Cocktail Book uit 1930, met een romantisch-mysterieuze naam die paste bij de speelse, licht gewaagde cocktailnamen van het Prohibition-tijdperk. Gin, kersenlikeur en droge vermout in gelijke, eenvoudige verhoudingen.",
  opera: "Een gin-cocktail uit het begin van de twintigste eeuw, met gin, vermout en een scheutje maraschino. De oudste recepten gebruiken Dubonnet in plaats van droge vermout. Waarom hij Opera heet, is niet bekend.",
  combined_forces: "Een moderne stirred-down cocktail die gin, Aperol en droge vermout in gelijke delen combineert, met een naam die luchtig verwijst naar hoe drie heel verschillende smaakprofielen (kruidig, bitter-zoet, droog) hier samen tot een verrassend uitgebalanceerde drank komen.",
  iceberg: "Een minimalistische, ijskoude cocktail van twee ingrediënten: wodka met een vleugje absint. De naam verwijst naar de heldere, ijzige uitstraling en naar de kracht die onder het oppervlak schuilt. Over de herkomst is weinig bekend.",
  abc_cocktail: "Een naam die de beginletters van de drie ingrediënten volgt: Amaretto, Bénédictine en Cognac. Twee zoete kruidenlikeuren en een brandewijn in gelijke delen, bedoeld als korte, warme afsluiter van de avond.",
  benedict: "Een eenvoudige cocktail, genoemd naar zijn belangrijkste smaakmaker: scotch met een scheut Bénédictine. Die kruidenlikeur werd in 1863 in Normandië bedacht door Alexandre Le Grand, die er het verhaal bij vertelde dat het recept van benedictijner monniken uit de zestiende eeuw kwam. Een goed voorbeeld van hoe een cocktail niet meer nodig heeft dan twee sterke smaken die elkaar aanvullen.",
  caen_caen: "Genoemd naar Caen, een stad in Normandië, de Franse streek die beroemd is om calvados (appelbrandewijn). In het glas gaat calvados samen met cognac, de druivenbrandewijn uit de streek rond de stad Cognac in Zuidwest-Frankrijk. De dubbele naam gaat vooral om de klank; de twee Franse brandewijnen vullen elkaar mooi aan.",
  harvard_cocktail: "Een vroeg twintigste-eeuwse, Amerikaans-collegiaal genoemde cocktail, net als de latere Yale Cocktail, met cognac, zoete vermout en Angostura in een structuur die sterk aan de Manhattan doet denken maar dan met cognac in plaats van whiskey.",
  kentucky_river: "Genoemd naar de rivier die door het hart van Kentucky's bourbon-county stroomt, waar het water traditioneel (via kalksteenlagen gefilterd) mede verantwoordelijk wordt gehouden voor de zachte smaak van lokale bourbon. Een simpele, aardse bourbon-sipper met een vleugje chocolade-likeur.",
  white_negroni: "Bedacht in 2001 door de Britse bartender Wayne Collins tijdens een wijnbeurs in Bordeaux. Hij verving de rode Campari van de klassieke Negroni door Suze, een Franse bitter van gentiaanwortel, en de zoete vermout door Lillet Blanc. Het resultaat is lichtgeel en bitterder, met meer citrus. Collins garneerde hem met een grapefruitschil, en die maakt echt verschil. Vertel je gasten dat deze \"witte\" Negroni in Frankrijk is bedacht, met Franse ingrediënten.",
  woodstock: "Genoemd naar het legendarische muziekfestival van 1969, een bourbon-honing-cocktail met een warme, aardse, bijna 'terug naar de natuur'-uitstraling die past bij de flower-power-associaties van die naam.",
  pink_gin: "Een negentiende-eeuwse gewoonte bij de Britse Koninklijke Marine. Angostura bitters werd aan boord gebruikt als middel tegen zeeziekte en maagklachten, en officieren mengden het door hun gin om het beter te laten smaken. De bitters kleurt de gin licht roze, vandaar de naam. Vertel je gasten dat dit een van de weinige cocktails is die uit een medicijnkastje kwam in plaats van uit een bar.",
  oyster_shot: "Een jaren-'80-'90-bartrend uit Amerika: een rauwe oester in een shotglas met wodka, tomatensap en hete sausjes, in één keer achterovergeslagen. Onderdeel van een bredere golf 'shooter'-cocktails uit die decennia die vooral bedoeld waren om indruk te maken, niet om lang van te genieten.",
  rum_old_fashioned: "De rum-toepassing van de klassieke Old Fashioned-formule (sterkedrank, suiker, bitters), populair in Caribische bars waar rum vanzelfsprekend de lokale basis-sterkedrank is in plaats van whiskey.",
  ritz_old_fashioned: "Een chique variant op de Old Fashioned met een scheutje champagne, genoemd naar de wereldberoemde Ritz-hotels in Parijs en Londen, waar hotelbars een traditie hebben van klassiekers net iets luxueuzer te maken dan het origineel.",
  japanese_cocktail: "Een van de recepten uit Jerry Thomas' \"How to Mix Drinks\" van 1862, het eerste Amerikaanse cocktailboek, en daarmee een van de oudste cocktails die nog worden gemaakt: cognac met orgeat en bitters. Er zit niets Japans in. De naam verwijst waarschijnlijk naar de eerste Japanse delegatie die in 1860 New York bezocht, een gebeurtenis waar de hele stad over sprak, vlak bij de bar waar Thomas toen werkte. Vertel je gasten dat ze hier een van de eerste opgeschreven cocktails proeven.",
  delft_donkey: "De Nederlandse variant op de Amerikaanse Moscow Mule, waarbij genever de wodka vervangt, genoemd naar de stad Delft. Een moderne, thuisbar-vriendelijke illustratie van hoe de simpele formule sterkedrank-gemberbier-limoen zich naar bijna elke nationale spirit laat vertalen.",
  east_side_cocktail: "Een moderne klassieker uit de New Yorkse cocktailscene van de jaren 2000, toegeschreven aan barman George Delgado van de bar Libation in de Lower East Side van Manhattan. In feite een gin-Gimlet met munt en komkommer, uit dezelfde beweging die ook de Southside weer nieuw leven inblies.",
  hong_kong_sling: "Een moderne knipoog naar de beroemde Singapore Sling, met gemberwijn in plaats van cherry brandy als belangrijkste smaakaccent, genoemd naar de andere grote Aziatische havenstad met een rijke koloniale bargeschiedenis.",
  camomile_collins: "Een moderne variant op de klassieke Tom Collins (de negentiende-eeuwse gin met citroen, suiker en bruiswater), waarbij kamille en honing de gewone suikersiroop vervangen. Onderdeel van de trend om de oude Collins-formule met steeds nieuwe, kruidige smaken te verrijken.",
  lemongrass_collins: "Net als de Camomile Collins een moderne variant op de klassieke Tom Collins, hier met een citroengras-accent dat de drank een Zuidoost-Aziatische twist geeft binnen de vertrouwde gin-citrus-soda-structuur.",
  cucumber_cooler: "Ontstaan in de kielzog van de komkommer-gin-trend die vanaf de jaren 2000 op gang kwam (mede aangewakkerd door merken als Hendrick's die komkommer als signatuurgarnering promootten). Een frisse, laagdrempelige highball die de klassieke Gin Fizz-structuur combineert met gemuddelde komkommer.",
  hedgerow_collins: "Genoemd naar de 'hedgerows', de dichte wilde heggen langs Engelse velden waar bramen in de late zomer volop groeien, en gebouwd op braambessenlikeur binnen de klassieke Tom Collins-structuur. Een typisch Brits-landelijke draai op een Amerikaans-Brits gedeeld cocktailformat.",
  orchard_collins: "Een appel-en-vlierbloesem-variant op de klassieke Tom Collins, met een naam die verwijst naar de Engelse boomgaarden ('orchards') waar appels en vlierbloesem in dezelfde periode rijpen.",
  fino_highball: "Onderdeel van de sherry-revival die vanaf de jaren 2010 in Londense en Spaanse cocktailbars op gang kwam, nadat sherry decennialang vooral als ouderwets aperitief werd gezien. Droge fino-sherry met tonic vormt een lichtere, minder alcoholische tegenhanger van de Gin Tonic.",
  texas_tea: "Een bourbon-gebaseerde neef van de beroemde Long Island Iced Tea uit de jaren '70, met een naam die simpelweg een andere grote Amerikaanse staat aanroept voor een even stevige, bedrieglijk drinkbare mix van meerdere sterkedranken achter een cola-smaak verstopt.",
  flora_dora: "Genoemd naar 'Florodora', een enorm populaire Broadway-musical uit 1900 die jarenlang volle zalen trok, in een tijd waarin cocktails vaak naar de theaterhits van het moment werden vernoemd. Gin met frambozensiroop, limoen en gemberbier, een fris, licht roze drankje passend bij de theatrale naam.",
  kurant_blush: "Ontstaan in de jaren '90, toen merken als Absolut met gearomatiseerde wodka's (zoals Absolut Kurant, met zwarte bes, uit 1992) een hele golf gekleurde, fruitige wodkacocktails op gang brachten. Cranberrysap geeft de drank zijn roze 'blush'-kleur.",
  on_the_lawn: "Een Pimm's-cocktail met een naam die rechtstreeks verwijst naar de Britse traditie van drinken op het gazon tijdens sportevenementen in de zomer, met Wimbledon als bekendste voorbeeld, waar Pimm's al decennia de officieuze huisdrank is.",
  earls_punch: "Een Britse gin-punch met een aristocratische naam ('Earl' is een Engelse graventitel), in de traditie van negentiende-eeuwse Engelse punches die vaak naar een adellijke gastheer of -vrouw werden genoemd die de drank op een feest liet serveren.",
  jalisco_swizzle: "Combineert tequila, genoemd naar de Mexicaanse staat Jalisco waar de meeste tequila vandaan komt, met de swizzle-techniek uit het Caribisch gebied: fijngestampt ijs snel ronddraaien met een swizzlestokje tot het glas beslaat. Een moderne fusie van twee heel verschillende drinktradities.",
  limon_mojito: "Een citroenvariant op de Cubaanse Mojito, waarbij een deel van het limoensap wordt vervangen door citroensap voor een net iets ander, scherper zuur profiel binnen dezelfde munt-rum-soda-structuur.",
  maid: "Een moderne, komkommer-en-muntgebaseerde wodka-cooler met een simpele, frisse 'tuin'-naam, onderdeel van dezelfde trend als de Cucumber Cooler en English Garden Fizz die komkommer als hoofdgarnering en smaakmaker gebruiken.",
  singapore_sling: "Bedacht rond 1915 door bartender Ngiam Tong Boon in de Long Bar van het Raffles Hotel in Singapore. Volgens het hotel was de drank bewust ontworpen om op vruchtensap te lijken, zodat vrouwen hem in het openbaar konden drinken in een tijd waarin het voor hen ongepast was om zichtbaar alcohol te bestellen. Het oorspronkelijke recept is verloren gegaan; de versie die nu bekend is, is later gereconstrueerd. Vertel je gasten dat wat eruitziet als een onschuldig fruitdrankje hier zou zijn ontstaan als slimme omweg rond een etiquetteregel.",
  english_garden_fizz: "Een moderne gin-fizz met komkommer en vlierbloesem, twee ingrediënten die onlosmakelijk verbonden zijn met het beeld van de Engelse landelijke tuin in de zomer, gebouwd op de eeuwenoude Fizz-structuur van sterkedrank, citrus en soda.",
  kings_fizz: "Een vereenvoudigde neef van de beroemde Ramos Gin Fizz uit New Orleans (Henry Ramos, 1888), die normaal room, oranjebloesemwater en minutenlang schudden vereist. Deze 'King's'-versie behoudt het eiwit voor de schuimlaag maar laat de zwaardere room achterwege voor een lichtere, snellere fizz.",
  bucks_fizz: "Bedacht in 1921 door bartender Pat McGarry in de Buck's Club in Londen, een paar jaar vóór de Franse Mimosa. Klassiek gaat er meer champagne in dan sinaasappelsap (ongeveer twee op één), terwijl een Mimosa meestal half om half is. Daardoor is de Bucks Fizz net iets droger en bruisender.",
  gorgeous_grace: "Een moderne champagne-cocktail met een speelse, feminiene naam, gebouwd op de eenvoudige, eeuwenoude combinatie van cognac en een vleugje grenadine getopt met bubbels, dezelfde structuur die klassiekers als de Champagne Cocktail al decennialang gebruiken.",
  honeydew: "Een moderne, met meloenlikeur getopte champagne-cocktail, genoemd naar de gelijknamige lichtgroene meloensoort waarvan de smaak dominant is. Onderdeel van dezelfde familie fruit-en-bubbels-cocktails als de Bellini en Rossini, maar met meloen in plaats van perzik of aardbei.",
  death_in_afternoon: "Ernest Hemingway's eigen recept, gepubliceerd in 1935 in 'So Red the Nose, or Breath in the Afternoon', een verzamelbundel met cocktailrecepten van beroemde schrijvers en acteurs uit die tijd. De naam knipoogt naar Hemingways eigen roman 'Death in the Afternoon' (1932) over Spaanse stierenvechten. Zijn eigen instructie luidde kort en droog: drink drie tot vijf van deze langzaam.",
  rossini: "Een prosecco-cocktail met aardbei, gemaakt naar het voorbeeld van de Bellini, die in Harry's Bar in Venetië werd bedacht en naar de schilder Giovanni Bellini is vernoemd. De Rossini is vernoemd naar de Italiaanse componist Gioachino Rossini. Zo ontstond een hele familie Venetiaanse fruit-en-bubbels-cocktails met namen van Italiaanse kunstenaars.",
  champagne_julep: "Een feestelijke versie van de Mint Julep, met champagne in plaats van bourbon of cognac. Hij staat al in Jerry Thomas' barboek uit 1862: munt, suiker en champagne over ijs. Lichter en bruisender dan de klassieke julep.",
  le_mans: "Genoemd naar de Franse stad die wereldberoemd is door de jaarlijkse 24 Uur van Le Mans-autorace, een cognac-cocktail met vlierbloesem die met een scheutje prosecco wordt afgetopt, als een net iets snellere, bruisende neef van de klassieke cognac-sours.",
  pink_sangria: "Een lichtere variant op de klassieke rode sangria, met witte wijn, sinaasappel en een scheutje grenadine dat de drank zijn roze kleur geeft, afgetopt met prosecco. Ideaal voor wie in de zomer liever iets frissers drinkt dan rode wijn.",
  sangria: "Het mengen van wijn met kruiden, honing en water is al eeuwenoud; de Romeinen deden het al om matige wijn drinkbaarder te maken. Op het Iberisch Schiereiland groeide die gewoonte uit tot wat we nu sangria noemen, met fruit en soms een scheut brandewijn. Internationaal bekend werd de drank pas nadat Spanje hem in 1964 liet proeven in zijn paviljoen op de Wereldtentoonstelling in New York. Vertel je gasten dat deze zomerse klassieker zijn wereldfaam aan één wereldtentoonstelling dankt.",
  sbagliato: "Ontstaan in 1972 bij Bar Basso in Milaan, toen barman Mirko Stocchetto in de drukte naar een fles mousserende wijn greep in plaats van gin voor een Negroni. Het resultaat smaakte zo goed dat de 'fout' bleef, met de naam 'sbagliato': 'verkeerd' of 'misgegaan' in het Italiaans. Vertel je gasten dat een van de bekendste moderne Italiaanse klassiekers uit een vergissing is ontstaan.",
  airmail: "Een Cubaanse cocktail met rum, honing, limoen en champagne, die in de jaren '30 in een Bacardi-boekje opdook en in 1949 in een Amerikaans gastenboek verscheen. De naam roept de glamour op van de vroege luchtpost, toen een brief per vliegtuig nog iets bijzonders was. Een minder bekende maar elegante neef van de French 75.",
  fish_house_punch: "Een van de oudste Amerikaanse punchrecepten, verbonden aan de Schuylkill Fishing Company, een herenclub in Philadelphia die in 1732 werd opgericht, nog vóór de Verenigde Staten bestonden. Volgens een bekend verhaal bezocht George Washington de club, en liet hij daarna drie dagen zijn dagboek leeg; dat verhaal is niet bewezen. Rum, cognac, perzik, citroen en suiker: vertel je gasten dat dit recept ouder is dan het land waar het vandaan komt.",
  bombay_punch: "Een rijke punch met cognac, sherry, maraschino, sinaasappellikeur en bubbels. Een Bombay Punch met die ingrediënten staat al in Jerry Thomas' barboek uit 1862. De naam verwijst naar Bombay (nu Mumbai): het woord 'punch' zelf komt waarschijnlijk uit India, waar Britse zeelieden in de zeventiende eeuw een drank van vijf ingrediënten leerden kennen.",
  haiti_punch: "Een Caribische rum-punch met tropisch fruit, genoemd naar Haïti, in de bredere traditie van eilandpunches die al eeuwenlang de basisformule sterkedrank-zuur-zoet-water gebruiken om rum drinkbaar en verkoelend te maken in het Caribische klimaat.",
  lolas_punch: "Een moderne, passievrucht-gebaseerde rumpunch met een persoonlijke naam, in dezelfde Caribische punch-traditie als de Haiti Punch en talloze andere op maat gemaakte rum-fruit-combinaties die elke eilandbar zijn eigen versie van heeft.",
  watermelon_punch: "Een moderne, zomerse rum-punch met watermeloen-associaties via de kleur en frisheid, populair als warm-weer-feestdrankje binnen de bredere traditie van vers-fruit-rum-punches.",
  surface_to_air: "Een moderne tiki-revival-cocktail met een dramatische, aan luchtvaart-en-militaire terminologie ontleende naam, typisch voor de eigentijdse tiki-scene die sinds de jaren 2000 graag teruggrijpt op de theatrale naamgevingsstijl van de originele tiki-pioniers als Don the Beachcomber en Trader Vic.",
  loving_cup: "Genoemd naar de Engelse traditie van de 'loving cup', een gedeelde drinkbeker die bij formele diners (nog altijd gebruikelijk aan universiteiten als Cambridge) van gast tot gast rondgaat als teken van gastvrijheid en verbondenheid. Deze cognac-sherry-punch met prosecco is bedoeld om op precies diezelfde manier gedeeld te worden.",
  june_bug: "Een zoete, tropische shooter-achtige cocktail uit de Amerikaanse Golfkust-bar-cultuur van de jaren '80-'90, genoemd naar de junikever, een veelvoorkomend Amerikaans insect. Bananen- en meloenlikeur met ananas en kokosroom maken 'm bijna een dessertdrankje.",
  santiago: "Genoemd naar Santiago de Cuba, de havenstad vlak bij de Daiquirí-baai en -mijn waar de Daiquiri zelf rond 1900 zou zijn ontstaan dankzij Amerikaanse mijningenieur Jennings Cox. Deze eenvoudige rum-limoen-grenadine-cocktail representeert een vroege, mogelijk parallelle formule uit dezelfde plek en periode als de beroemdere Daiquiri.",
  canadian_daisy: "Onderdeel van de negentiende-eeuwse 'Daisy'-familie (sterkedrank, citrus, zoetmiddel, een likeur-accent, getopt met soda), hier met rye whiskey, Canada's signatuur-graanwhisky, in plaats van de gebruikelijke Amerikaanse bourbon.",
  agave_julep: "Een tequila-variant op de klassieke Mint Julep uit Kentucky, waarbij agavesiroop (gewonnen uit dezelfde plant als tequila zelf) de suikersiroop vervangt voor een dubbele agave-connectie in één glas.",
  georgia_julep: "Een perzikvariant op de Mint Julep, genoemd naar de staat Georgia, die in Amerika bekendstaat om zijn perziken. Al in Jerry Thomas' barboek van 1862 staat een Georgia Mint Julep, toen met cognac en perzikbrandy. Deze versie gebruikt bourbon en perziklikeur, met munt en een beetje suiker.",
  jaffa: "Genoemd naar de Jaffa-sinaasappel, de beroemde citrusvariëteit uit het Midden-Oosten die ook de naam gaf aan de populaire Britse chocolade-sinaasappelkoekjes 'Jaffa Cakes'. Cognac met triple sec en crème de cacao roept precies diezelfde chocolade-sinaasappel-combinatie op in vloeibare vorm.",
  sake_martini: "Ontstaan in de jaren '90-2000, toen sake buiten Japan langzaam een plek veroverde in westerse cocktailbars en bartenders het graag combineerden met wodka voor een zachtere, licht zoete 'saketini', onderdeel van een bredere golf Oost-West-fusiecocktails uit die periode.",
  valentine_martini: "Een roze, cranberry-gebaseerde wodka-Martini met een naam die rechtstreeks naar Valentijnsdag verwijst, onderdeel van de bredere traditie van seizoensgebonden, gelegenheidsgebonden cocktailnamen die vooral rond feestdagen op cocktailkaarten verschijnen.",
  egg_nog: "Gaat terug op de Engelse 'posset', een warme melk-eier-drank uit de middeleeuwen, die kolonisten meenamen naar Amerika. Daar werd rum (goedkoper dan de Europese sherry en Madeira die de Britse versie gebruikte) de gangbare basis, en omdat eieren en zuivel er ruimer voorhanden waren dan in Engeland, groeide de drank uit tot een specifiek Amerikaans kersttraditie. Vertel je gasten dat wat nu als hét feestdagendrankje geldt, ooit gewoon een praktische aanpassing was aan wat lokaal beschikbaar en betaalbaar was.",
  breakfast_martini: "Bedacht in de jaren '90 door de Londense bartender Salvatore Calabrese, naar eigen zeggen omdat zijn vrouw op een ochtend vroeg om iets met haar sinaasappelmarmelade bij het ontbijt. Hij improviseerde met gin, triple sec, citroensap en een schep marmelade, en creëerde daarmee een cocktail die inmiddels als moderne klassieker geldt. Vertel je gasten dat dit een van de weinige klassiekers is waarvan de bedenker, het jaar en zelfs de exacte aanleiding (marmelade bij het ontbijt) nog precies bekend zijn.",
};

